		// than asserting either way.
		return nil, nil
	}
	short := sha
	if len(short) > 7 {
		short = short[:7]
	}
	return []associatedCommit{{
		SHA:      sha,
		ShortSHA: short,
		Message:  info.CommitSubject,
		Author:   info.CommitAuthor,
		Date:     parseAPITime(info.CommitDate),
