func (r *apiCheckpointReader) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.Metadata, string, error) {
	info, err := r.loadDetail(ctx, checkpointID)
	if err != nil {
		return nil, "", err
