85→// Binary files are silently excluded from attribution calculations because line-based\n    86→// diffing doesn't apply to binary content. This means binary files (images, compiled\n    87→// binaries, etc.) won't appear in attribution metrics even if they were added or modified.\n    88→// This is intentional - attribution measures code contributions via line counting,\n    89→// which only makes sense for text files.\n    90→//\n    91→// Uses go-git's IsBinary() which implements git's binary detection algorithm.\n    92→//\n    93→// TODO: Consider tracking binary file counts separately (e.g., BinaryFilesChanged field)\n    94→// to provide visibility into non-text file modifications.\n    95→func getFileContent(tree *object.Tree, path string) string {\n    96→\tif tree == nil {\n    97→\t\treturn \"\"\n    98→\t}\n    99→\n   100→\tfile, err := tree.File(path)\n   101→\tif err != nil {\n   102→\t\treturn \"\"\n   103→\t}\n   104→\n   105→\t// Use git's binary detection algorithm\n   106→\tisBinary, err := file.IsBinary()\n   107→\tif err != nil || isBinary {\n   108→\t\treturn \"\"\n   109→\t}\n   110→\n   111→\tcontent, err := file.Contents()\n   112→\tif err != nil {\n   113→\t\treturn \"\"\n   114→\t}\n   115→\n   116→\treturn content\n   117→}\n   118→\n   119→// diffLines compares two strings and returns line-level diff stats.\n   120→// Returns (unchanged, added, removed) line counts.\n   121→func diffLines(checkpointContent, committedContent string) (unchanged, added, removed int) {\n   122→\t// Handle edge cases\n   123→\tif checkpointContent == committedContent {\n   124→\t\treturn countLinesStr(committedContent), 0, 0\n   125→\t}\n   126→\tif checkpointContent == \"\" {\n   127→\t\treturn 0, countLinesStr(committedContent), 0\n   128→\t}\n   129→\tif committedContent == \"\" {\n   130→\t\treturn 0, 0, countLinesStr(checkpointContent)\n   131→\t}\n   132→\n   133→\tdmp := diffmatchpatch.New()\n   134→\n   135→\t// Convert to line-based diff using DiffLinesToChars/DiffCharsToLines pattern\n   136→\ttext1, text2, lineArray := dmp.DiffLinesToChars(checkpointContent, committedContent)\n   137→\tdiffs := dmp.DiffMain(text1, text2, false)\n   138→\tdiffs = dmp.DiffCharsToLines(diffs, lineArray)\n   139→\n   140→\tfor _, d := range diffs {\n   141→\t\tlines := countLinesStr(d.Text)\n   142→\t\tswitch d.Type {\n   143→\t\tcase diffmatchpatch.DiffEqual:\n   144→\t\t\tunchanged += lines\n   145→\t\tcase diffmatchpatch.DiffInsert:\n   146→\t\t\tadded += lines\n   147→\t\tcase diffmatchpatch.DiffDelete:\n   148→\t\t\tremoved += lines\n   149→\t\t}\n   150→\t}\n   151→\n   152→\treturn unchanged, added, removed\n   153→}\n   154→\n   155→// countLinesStr returns the number of lines in a string.\n   156→// An empty string has 0 lines. A string without newlines has 1 line.\n   157→// This is used for both file content and diff text segments.\n   158→func countLinesStr(content string) int {\n   159→\tif content == \"\" {\n   160→\t\treturn 0\n   161→\t}\n   162→\tlines := strings.Count(content, \"\\n\")\n   163→\t// If content doesn't end with newline, add 1 for the last line\n   164→\tif !strings.HasSuffix(content, \"\\n\") {\n   165→\t\tlines++\n   166→\t}\n   167→\treturn lines\n   168→}\n   169→\n   170→// CalculateAttributionWithAccumulated computes final attribution using accumulated prompt data.\n   171→// This provides more accurate attribution than tree-only comparison because it captures\n   172→// user edits that happened between checkpoints (which would otherwise be mixed into the\n   173→// checkpoint snapshots).\n   174→//\n   175→// The calculation:\n   176→// 1. Sum user edits from PromptAttributions (captured at each prompt start)\n   177→// 2. Add user edits after the final checkpoint (shadow → head diff)\n   178→// 3. Calculate agent lines from base → shadow\n   179→// 4. Estimate user self-modifications vs agent modifications using per-file tracking\n   180→// 5. Compute percentages\n   181→//\n   182→// attributionBaseCommit and headCommitHash are optional commit hashes for fast non-agent\n   183→// file detection via git diff-tree. When empty, falls back to go-git tree walk.\n   184→//\n   185→// Note: Binary files (detected by null bytes) are silently excluded from attribution\n   186→// calculations since line-based diffing only applies to text files.\n   187→//\n   188→// See docs/architecture/attribution.md for details on the per-file tracking approach.\n   189→func CalculateAttributionWithAccumulated(\n   190→\tctx context.Context,\n   191→\tbaseTree *object.Tree,\n   192→\tshadowTree *object.Tree,\n   193→\theadTree *object.Tree,\n   194→\tfilesTouched []string,\n   195→\tpromptAttributions []PromptAttribution,\n   196→\trepoDir string,\n   197→\tattributionBaseCommit string,\n   198→\theadCommitHash string,\n   199→) *checkpoint.InitialAttribution {\n   200→\tif len(filesTouched) == 0 {\n   201→\t\treturn nil\n   202→\t}\n   203→\n   204→\t// Sum accumulated user lines from prompt attributions\n   205→\t// Also aggregate per-file user additions for accurate modification tracking\n   206→\tvar accumulatedUserAdded, accumulatedUserRemoved int\n   207→\taccumulatedUserAddedPerFile := make(map[string]int)\n   208→\tfor _, pa := range promptAttributions {\n   209→\t\taccumulatedUserAdded += pa.UserLinesAdded\n   210→\t\taccumulatedUserRemoved += pa.UserLinesRemoved\n   211→\t\t// Merge per-file data from all prompt attributions\n   212→\t\tfor filePath, added := range pa.UserAddedPerFile {\n   213→\t\t\taccumulatedUserAddedPerFile[filePath] += added\n   214→\t\t}\n   215→\t}\n   216→\n   217→\t// Calculate attribution for agent-touched files\n   218→\t// IMPORTANT: shadowTree is a snapshot of the worktree at checkpoint time,\n   219→\t// which includes both agent work AND accumulated user edits (to agent-touched files).\n   220→\t// So base→shadow diff = (agent work + accumulated user work to these files).\n   221→\tvar totalAgentAndUserWork int\n   222→\tvar post