==========\n   278→\t// VERIFY ATTRIBUTION FOR DELETION-ONLY COMMIT\n   279→\t// ========================================\n   280→\tt.Log(\"Verifying attribution for deletion-only commit\")\n   281→\n   282→\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n   283→\tif err != nil {\n   284→\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n   285→\t}\n   286→\n   287→\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n   288→\tif err != nil {\n   289→\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n   290→\t}\n   291→\n   292→\tsessionsTree, err := sessionsCommit.Tree()\n   293→\tif err != nil {\n   294→\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n   295→\t}\n   296→\n   297→\t// Read session-level metadata.json (InitialAttribution is in 0/metadata.json)\n   298→\tmetadataPath := SessionMetadataPath(checkpointID.String())\n   299→\tmetadataFile, err := sessionsTree.File(metadataPath)\n   300→\tif err != nil {\n   301→\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n   302→\t}\n   303→\n   304→\tmetadataContent, err := metadataFile.Contents()\n   305→\tif err != nil {\n   306→\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n   307→\t}\n   308→\n   309→\tvar metadata checkpoint.CommittedMetadata\n   310→\tif err := json.Unmarshal([]byte(metadataContent), \u0026metadata); err != nil {\n   311→\t\tt.Fatalf(\"Failed to parse metadata.json: %v\", err)\n   312→\t}\n   313→\n   314→\tif metadata.InitialAttribution == nil {\n   315→\t\tt.Fatal(\"InitialAttribution is nil\")\n   316→\t}\n   317→\n   318→\tattr := metadata.InitialAttribution\n   319→\tt.Logf(\"Attribution (deletion-only): agent=%d, human_added=%d, human_removed=%d, total=%d, percentage=%.1f%%\",\n   320→\t\tattr.AgentLines, attr.HumanAdded, attr.HumanRemoved,\n   321→\t\tattr.TotalCommitted, attr.AgentPercentage)\n   322→\n   323→\t// For deletion-only commits where agent makes no additions:\n   324→\t// - Agent removed oldFunc1 (made deletions, not additions)\n   325→\t// - AgentLines = 0 (no additions)\n   326→\t// - User removed oldFunc2 and oldFunc3\n   327→\t// - HumanAdded = 0 (no new lines)\n   328→\t// - HumanRemoved = number of lines user deleted\n   329→\t// - TotalCommitted = 0 (no additions from anyone)\n   330→\t// - AgentPercentage = 0 (by convention for deletion-only)\n   331→\n   332→\tif attr.AgentLines != 0 {\n   333→\t\tt.Errorf(\"AgentLines = %d, want 0 (agent made no additions, only deletions)\", attr.AgentLines)\n   334→\t}\n   335→\n   336→\tif attr.HumanAdded != 0 {\n   337→\t\tt.Errorf(\"HumanAdded = %d, want 0 (no new lines in deletion-only commit)\", attr.HumanAdded)\n   338→\t}\n   339→\n   340→\t// User removed 2 remaining functions + 1 blank line (3 lines total)\n   341→\tif attr.HumanRemoved != 3 {\n   342→\t\tt.Errorf(\"HumanRemoved = %d, want 3 (removed blank + 2 functions = 3 lines)\", attr.HumanRemoved)\n   343→\t}\n   344→\n   345→\tif attr.TotalCommitted != 0 {\n   346→\t\tt.Errorf(\"TotalCommitted = %d, want 0 (deletion-only commit has no net additions)\", attr.TotalCommitted)\n   347→\t}\n   348→\n   349→\tif attr.AgentPercentage != 0 {\n   350→\t\tt.Errorf(\"AgentPercentage = %.1f%%, want 0 (deletion-only commit)\",\n   351→\t\t\tattr.AgentPercentage)\n   352→\t}\n   353→}\n   354→\n   355→// TestManualCommit_AttributionNoDoubleCount tests that PromptAttributions are\n   356→// cleared after condensation to prevent double-counting on subsequent commits.\n   357→//\n   358→// Bug scenario:\n   359→// 1. Checkpoint 1 → user edits → commit (condensation, PromptAttributions used)\n   360→// 2. StepCount reset to 0, but PromptAttributions NOT cleared\n   361→// 3. Checkpoint 2 → new PromptAttributions appended to old ones\n   362→// 4. Second commit → CalculateAttributionWithAccumulated sums ALL PromptAttributions\n   363→// 5. User edits from first commit are double-counted\n   364→func TestManualCommit_AttributionNoDoubleCount(t *testing.T) {\n   365→\tt.Parallel()\n   366→\tenv := NewTestEnv(t)\n   367→\tdefer env.Cleanup()\n   368→\n   369→\tenv.InitRepo()\n   370→\n   371→\t// Create initial commit\n   372→\tenv.WriteFile(\"main.go\", \"package main\\n\")\n   373→\tenv.GitAdd(\"main.go\")\n   374→\tenv.GitCommit(\"Initial commit\")\n   375→\n   376→\tenv.InitEntire()\n   377→\n   378→\t// ========================================\n   379→\t// FIRST CYCLE: Checkpoint → user edit → commit\n   380→\t// ========================================\n   381→\tt.Log(\"First cycle: agent checkpoint + user edit + commit\")\n   382→\n   383→\tsession := env.NewSession()\n   384→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n   385→\t\tt.Fatalf(\"SimulateUserPromptSubmit (first cycle) failed: %v\", err)\n   386→\t}\n   387→\n   388→\t// Agent adds 5 lines\n   389→\tcheckpoint1Content := \"package main\\n\\nfunc agent1() { return 1 }\\nfunc agent2() { return 2 }\\nfunc agent3() { return 3 }\\n\"\n   390→\tenv.WriteFile(\"main.go\", checkpoint1Content)\n   391→\n   392→\tsession.CreateTranscript(\n   393→\t\t\"Add agent functions\",\n   394→\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint1Content}},\n   395→\t)\n   396→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n   397→\t\tt.Fatalf(\"SimulateStop (first cycle) failed: %v\", err)\n   398→\t}\n   399→\n   400→\t// User adds 2 lines between checkpoints\n   401→\tuserEdit1Content := checkpoint1Content + \"// User comment 1\\n// User comment 2\\n\"\n   402→\tenv.WriteFile(\"main.go\", userEdit1Content)\n   403→\n   404→\t// Commit with hooks (condensation happens)\n   405→\tenv.GitCommitWithShadowHooks(\"First commit\", \"main.go\")\n   406→\n   407→\t// Get first commit's checkpoint ID\n   408→\trepo, err := git.PlainOpen(env.RepoDir)\n   409→\tif err != nil {\n   410→\t\tt.Fatalf(\"failed to open repo: %v\", err)\n   411→\t}\n   412→\n   413→\thead, err := repo.Head()\n   414→\tif err != nil {\n   415→\t\tt.Fatalf(\"failed to get HEAD: %v\", err)\n   416→\t}\n   417→\n   418→\tcommit1, err := repo.CommitObject(head.Hash())\n   419→\tif err != nil {\n   420→\t\tt.Fatalf(\"failed to get commit: %v\", err)\n   421→\t}\n   422→\n   423→\tcheckpointID1, found := trailers.ParseCheckpoint(commit1.Message)\n   424→\tif !found {\n   425→\t\tt.Fatal(\"First commit should have checkpoint trailer\")\n   426→\t}\n   427→\n   428→\tt.Logf(\"First commit checkpoint ID: %s\", checkpointID1)\n   429→\n   430→\t// Verify first commit attribution\n   431→\tattr1 := getAttributionFromMetadata(t, repo, checkpointID1)\n   432→\tt.Logf(\"First commit attribution: agent=%d, human_added=%d, total=%d\",\n   433→\t\tattr1.AgentLines, attr1.HumanAdded, attr1.TotalCommitted)\n   434→\n   435→\t// First commit should have:\n   436→\t// - Agent: 4 lines (3 functions + 1 blank)\n   437→\t// - User: 2 lines (2 comments)\n   438→\t// - Total: 6 lines\n   439→\tif attr1.HumanAdded != 2 {\n   440→\t\tt.Errorf(\"First commit HumanAdded = %d, want 2\", attr1.HumanAdded)\n   441→\t}\n   442→\n   443→\t// ========================================\n   444→\t// SECOND CYCLE: New checkpoint → user edit → commit\n   445→\t// ========================================\n   446→\tt.Log(\"Second cycle: new agent checkpoint + user edit + commit\")\n   447→\n   448→\t// Simulate new prompt (should calculate attribution, which should be empty after reset)\n   449→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n   450→\t\tt.Fatalf(\"SimulateUserPromptSubmit (second cycle) failed: %v\", err)\n   451→\t}\n   452→\n   453→\t// Agent adds 3 more lines\n   454→\tcheckpoint2Content := userEdit1Content + \"\\nfunc agent4() { return 4 }\\nfunc agent5() { return 5 }\\n\"\n   455→\tenv.WriteFile(\"main.go\", checkpoint2Content)\n   456→\n   457→\tsession.CreateTranscript(\n   458→\t\t\"Add more agent functions\",\n   459→\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint2Content}},\n   460→\t)\n   461→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n   462→\t\tt.Fatalf(\"SimulateStop (second cycle) failed: %v\", err)\n   463→\t}\n   464→\n   465→\t// User adds 1 more line\n   466→\tuserEdit2Content := checkpoint2Content + \"// User comment 3\\n\"\n   467→\tenv.WriteFile(\"main.go\", userEdit2Content)\n   468→\n   469→\t// Second commit (another condensation)\n   470→\tenv.GitCommitWithShadowHooks(\"Second commit\", \"main.go\")\n   471→\n   472→\t// Get second commit's checkpoint ID\n   473→\thead, err = repo.Head()\n   474→\tif err != nil {\n   475→\t\tt.Fatalf(\"failed to get HEAD after second commit: %v\", err)\n   476→\t}\n   477→\n   478→\tcommit2, err := repo.CommitObject(head.Hash())\n   479→\tif err != nil {\n   480→\t\tt.Fatalf(\"failed to get second commit: %v\", err)\n   481→\t}\n   482→\n   483→\tcheckpointID2, found := trailers.ParseCheckpoint(commit2.Message)\n   484→\tif !found {\n   485→\t\tt.Fatal(\"Second commit should have checkpoint trailer\")\n   486→\t}\n   487→\n   488→\tt.Logf(\"Second commit checkpoint ID: %s\", checkpointID2)\n   489→\n   490→\t// Verify second commit attribution\n   491→\tattr2 := getAttributionFromMetadata(t, repo, checkpointID2)\n   492→\tt.Logf(\"Second commit attribution: agent=%d, human_added=%d, total=%d\",\n   493→\t\tattr2.AgentLines, attr2.HumanAdded, attr2.TotalCommitted)\n   494→\n   495→\t// Second commit should have (since first commit):\n   496→\t// - Agent: 3 lines (2 functions + 1 blank)\n   497→\t// - User: 1 line (1 comment)\n   498→\t// - Total: 4 lines\n   499→\t//\n   500→\t// BUG (if not fixed): HumanAdded would be 3 (1 new + 2 from first commit double-counted)\n   501→\t// CORRECT (after fix): HumanAdded should be 1 (only new user edits)\n   502→\n   503→\tif attr2.HumanAdded != 1 {\n   504→\t\tt.Errorf(\"Second commit HumanAdded = %d, want 1 (should NOT double-count first commit's 2 user lines)\",\n   505→\t\t\tattr2.HumanAdded)\n   506→\t}\n   507→\n   508→\tif attr2.TotalCommitted != 4 {\n   509→\t\tt.Errorf(\"Second commit TotalCommitted = %d, want 4 (3 agent + 1 user)\",\n   510→\t\t\tattr2.TotalCommitted)\n   511→\t}\n   512→\n   513→\t// Agent percentage should be 3/4 = 75%\n   514→\tif attr2.AgentPercentage \u003c 74.9 || attr2.AgentPercentage \u003e 75.1 {\n   515→\t\tt.Errorf(\"Second commit AgentPercentage = %.1f%%, want 75.0%%\", attr2.AgentPercentage)\n   516→\t}\n   517→}\n   518→\n   519→// getAttributionFromMetadata reads attribution from a checkpoint on entire/checkpoints/v1 branch.\n   520→// InitialAttribution is stored in session-level metadata (0/metadata.json).\n   521→func getAttributionFromMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) *checkpoint.InitialAttribution {\n   522→\tt.Helper()\n   523→\n   524→\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n   525→\tif err != nil {\n   526→\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n   527→\t}\n   528→\n   529→\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n   530→\tif err != nil {\n   531→\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n   532→\t}\n   533→\n   534→\tsessionsTree, err := sessionsCommit.Tree()\n   535→\tif err != nil {\n   536→\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n   537→\t}\n   538→\n   539→\t// Read session-level metadata (InitialAttribution is in 0/metadata.json)\n   540→\tmetadataPath := SessionMetadataPath(checkpointID.String())\n   541→\tmetadataFile, err := sessionsTree.File(metadataPath)\n   542→\tif err != nil {\n   543→\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n   544→\t}\n   545→\n   546→\tmetadataContent, err := metadataFile.Contents()\n   547→\tif err != nil {\n   548→\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n   549→\t}\n   550→\n   551→\tvar metadata checkpoi