\n  1185→\t\t\tstate.BaseCommit = newHead\n  1186→\t\t\tif err := s.saveSessionState(ctx, state); err != nil {\n  1187→\t\t\t\tlogging.Warn(logCtx, \"failed to update session state\",\n  1188→\t\t\t\t\tslog.String(\"session_id\", state.SessionID),\n  1189→\t\t\t\t\tslog.String(\"error\", err.Error()))\n  1190→\t\t\t}\n  1191→\t\t}\n  1192→\t}\n  1193→}\n  1194→\n  1195→// truncateHash safely truncates a git hash to 7 chars for logging.\n  1196→func truncateHash(h string) string {\n  1197→\tif len(h) > 7 {\n  1198→\t\treturn h[:7]\n  1199→\t}\n  1200→\treturn h\n  1201→}\n  1202→"}]},"uuid":"cd974e30-5e70-43e9-830f-448b3377062e","timestamp":"2026-03-27T08:47:57.279Z","toolUseResult":{"type":"text","file":{"filePath":"/repo/cli/cmd/entire/cli/strategy/manual_commit_hooks.go","content":"// postCommitUpdateBaseCommitOnly updates BaseCommit for all sessions on the current\n// worktree when a commit has no Entire-Checkpoint trailer. This prevents BaseCommit\n// from going stale, which would cause future PrepareCommitMsg calls to skip the\n// session (BaseCommit != currentHeadHash filter).\n//\n// Unlike the full PostCommit flow, this does NOT fire EventGitCommit or trigger\n// condensation — it only keeps BaseCommit in sync with HEAD.\nfunc (s *ManualCommitStrategy) postCommitUpdateBaseCommitOnly(ctx context.Context, head *plumbing.Reference) {\n\tlogCtx := logging.WithComponent(ctx, \"checkpoint\")\n\tworktreePath, err := paths.WorktreeRoot(ctx)\n\tif err != nil {\n\t\treturn // Silent failure — hooks must be resilient\n\t}\n\n\tsessions, err := s.findSessionsForWorktree(ctx, worktreePath)\n\tif err != nil || len(sessions) == 0 {\n\t\treturn\n\t}\n\n\tnewHead := head.Hash().String()\n\tfor _, state := range sessions {\n\t\t// Only update active sessions. Idle/ended sessions are kept around for\n\t\t// LastCheckpointID reuse and should not be advanced to HEAD.\n\t\tif !state.Phase.IsActive() {\n\t\t\tcontinue\n\t\t}\n\t\tif state.BaseCommit != newHead {\n\t\t\tlogging.Debug(logCtx, \"post-commit (no trailer): updating BaseCommit\",\n\t\t\t\tslog.String(\"session_id\", state.SessionID),\n\t\t\t\tslog.String(\"old_base\", truncateHash(state.BaseCommit)),\n\t\t\t\tslog.String(\"new_head\", truncateHash(newHead)),\n\t\t\t)\n\t\t\tstate.BaseCommit = newHead\n\t\t\tif err := s.saveSessionState(ctx, state); err != nil {\n\t\t\t\tlogging.Warn(logCtx, \"failed to update session state\",\n\t\t\t\t\tslog.String(\"session_id\", state.SessionID),\n\t\t\t\t\tslog.String(\"error\", err.Error()))\n\t\t\t}\n\t\t}\n\t}\n}\n\n// truncateHash safely truncates a git hash to 7 chars for logging.\nfunc truncateHash(h string) string {\n\tif len(h) > 7 {\n\t\treturn h[:7]\n\t}\n\treturn h\n}\n","numLines":50,"startLine":1153,"totalLines":2476}},"sourceToolAssistantUUID":"5bc9ade2-ed21-44f6-9d9b-1fd4b235ff5e","userType":"external","entrypoint":"cli","cwd":"/repo/cli","sessionId":"466e2cb2-1cca-4296-8efd-ef4bb139d9c3","version":"2.1.85","gitBranch":"main","slug":"gentle-wishing-ladybug"}
