sion()\n    47→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n    48→\t\tt.Fatalf(\"SimulateUserPromptSubmit (prompt 1) failed: %v\", err)\n    49→\t}\n    50→\n    51→\t// Agent adds 4 lines\n    52→\tcheckpoint1Content := \"package main\\n\\nfunc agentFunc() {\\n\\treturn 42\\n}\\n\"\n    53→\tenv.WriteFile(\"main.go\", checkpoint1Content)\n    54→\n    55→\tsession.CreateTranscript(\n    56→\t\t\"Add agent function\",\n    57→\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint1Content}},\n    58→\t)\n    59→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n    60→\t\tt.Fatalf(\"SimulateStop (checkpoint 1) failed: %v\", err)\n    61→\t}\n    62→\n    63→\t// ========================================\n    64→\t// USER EDITS between checkpoints\n    65→\t// ========================================\n    66→\tt.Log(\"User makes edits between checkpoints\")\n    67→\n    68→\t// User adds 5 comment lines\n    69→\tuserContent := checkpoint1Content +\n    70→\t\t\"// User comment 1\\n\" +\n    71→\t\t\"// User comment 2\\n\" +\n    72→\t\t\"// User comment 3\\n\" +\n    73→\t\t\"// User comment 4\\n\" +\n    74→\t\t\"// User comment 5\\n\"\n    75→\tenv.WriteFile(\"main.go\", userContent)\n    76→\n    77→\t// ========================================\n    78→\t// CHECKPOINT 2: New prompt (attribution calculated)\n    79→\t// ========================================\n    80→\tt.Log(\"User enters new prompt (attribution should capture 5 user lines)\")\n    81→\n    82→\t// Simulate UserPromptSubmit hook - this calculates attribution at prompt start\n    83→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n    84→\t\tt.Fatalf(\"SimulateUserPromptSubmit (prompt 2) failed: %v\", err)\n    85→\t}\n    86→\n    87→\t// Agent adds another function (4 more lines)\n    88→\tcheckpoint2Content := userContent + \"\\nfunc agentFunc2() {\\n\\treturn 100\\n}\\n\"\n    89→\tenv.WriteFile(\"main.go\", checkpoint2Content)\n    90→\n    91→\tsession.CreateTranscript(\n    92→\t\t\"Add second agent function\",\n    93→\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint2Content}},\n    94→\t)\n    95→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n    96→\t\tt.Fatalf(\"SimulateStop (checkpoint 2) failed: %v\", err)\n    97→\t}\n    98→\n    99→\t// Verify 2 rewind points\n   100→\tpoints := env.GetRewindPoints()\n   101→\tif len(points) != 2 {\n   102→\t\tt.Fatalf(\"Expected 2 rewind points, got %d\", len(points))\n   103→\t}\n   104→\n   105→\t// ========================================\n   106→\t// USER COMMITS: Condensation happens\n   107→\t// ========================================\n   108→\tt.Log(\"User commits (condensation should happen)\")\n   109→\n   110→\t// Commit using hooks (this triggers condensation)\n   111→\tenv.GitCommitWithShadowHooks(\"Add functions\", \"main.go\")\n   112→\n   113→\t// Get commit hash and checkpoint ID\n   114→\theadHash := env.GetHeadHash()\n   115→\tt.Logf(\"User commit: %s\", headHash[:7])\n   116→\n   117→\trepo, err := git.PlainOpen(env.RepoDir)\n   118→\tif err != nil {\n   119→\t\tt.Fatalf(\"failed to open repo: %v\", err)\n   120→\t}\n   121→\n   122→\tcommitObj, err := repo.CommitObject(plumbing.NewHash(headHash))\n   123→\tif err != nil {\n   124→\t\tt.Fatalf(\"failed to get commit object: %v\", err)\n   125→\t}\n   126→\n   127→\tcheckpointID, found := trailers.ParseCheckpoint(commitObj.Message)\n   128→\tif !found {\n   129→\t\tt.Fatal(\"Commit should have Entire-Checkpoint trailer\")\n   130→\t}\n   131→\tt.Logf(\"Checkpoint ID: %s\", checkpointID)\n   132→\n   133→\t// ========================================\n   134→\t// VERIFY ATTRIBUTION\n   135→\t// ========================================\n   136→\tt.Log(\"Verifying attribution in metadata\")\n   137→\n   138→\t// Read metadata from entire/checkpoints/v1 branch\n   139→\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n   140→\tif err != nil {\n   141→\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n   142→\t}\n   143→\n   144→\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n   145→\tif err != nil {\n   146→\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n   147→\t}\n   148→\n   149→\tsessionsTree, err := sessionsCommit.Tree()\n   150→\tif err != nil {\n   151→\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n   152→\t}\n   153→\n   154→\t// Read session-level metadata.json from sharded path (InitialAttribution is in 0/metadata.json)\n   155→\tmetadataPath := SessionMetadataPath(checkpointID.String())\n   156→\tmetadataFile, err := sessionsTree.File(metadataPath)\n   157→\tif err != nil {\n   158→\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n   159→\t}\n   160→\n   161→\tmetadataContent, err := metadataFile.Contents()\n   162→\tif err != nil {\n   163→\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n   164→\t}\n   165→\n   166→\tvar metadata checkpoint.CommittedMetadata\n   167→\tif err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {\n   168→\t\tt.Fatalf(\"Failed to parse metadata.json: %v\", err)\n   169→\t}\n   170→\n   171→\t// Verify InitialAttribution exists\n   172→\tif metadata.InitialAttribution == nil {\n   173→\t\tt.Fatal(\"InitialAttribution is nil\")\n   174→\t}\n   175→\n   176→\tattr := metadata.InitialAttribution\n   177→\tt.Logf(\"Attribution: agent=%d, human_added=%d, human_modified=%d, human_removed=%d, total=%d, percentage=%.1f%%\",\n   178→\t\tattr.AgentLines, attr.HumanAdded, attr.HumanModified, attr.HumanRemoved,\n   179→\t\tattr.TotalCommitted, attr.AgentPercentage)\n   180→\n   181→\t// Verify attribution was calculated and has reasonable values\n   182→\t// Note: The shadow branch includes all worktree changes (agent + user),\n   183→\t// so base→shadow diff includes user edits that were present during SaveStep.\n   184→\t// The attribution separates them using PromptAttributions.\n   185→\t//\n   186→\t// Expected: agent=13 (base→shadow includes user comments in worktree)\n   187→\t//           human=5 (from PromptAttribution)\n   188→\t//           total=18 (net additions)\n   189→\t//\n   190→\t// This tests that:\n   191→\t// 1. Attribution is calculated and stored\n   192→\t// 2. PromptAttribution captured user edits between checkpoints\n   193→\t// 3. Percentages are computed\n   194→\tif attr.AgentLines <= 0 {\n   195→\t\tt.Errorf(\"AgentLines = %d, should be > 0\", attr.AgentLines)\n   196→\t}\n   197→\n   198→\tif attr.HumanAdded != 5 {\n   199→\t\tt.Errorf(\"HumanAdded = %d, want 5 (5 comments captured in PromptAttribution)\",\n   200→\t\t\tattr.HumanAdded)\n   201→\t}\n   202→\n   203→\tif attr.TotalCommitted <= 0 {\n   204→\t\tt.Errorf(\"TotalCommitted = %d, should be > 0\", attr.TotalCommitted)\n   205→\t}\n   206→\n   207→\tif attr.AgentPercentage <= 0 || attr.AgentPercentage >= 100 {\n   208→\t\tt.Errorf(\"AgentPercentage = %.1f%%, should be between 0 and 100\",\n   209→\t\t\tattr.AgentPercentage)\n   210→\t}\n   211→}\n   212→\n   213→// TestManualCommit_AttributionDeletionOnly tests attribution for deletion-only commits\n   214→func TestManualCommit_AttributionDeletionOnly(t *testing.T) {\n   215→\tt.Parallel()\n   216→\tenv := NewTestEnv(t)\n   217→\tdefer env.Cleanup()\n   218→\n   219→\tenv.InitRepo()\n   220→\n   221→\t// Create initial commit with content\n   222→\tinitialContent := \"package main\\n\\nfunc oldFunc1() {}\\nfunc oldFunc2() {}\\nfunc oldFunc3() {}\\n\"\n   223→\tenv.WriteFile(\"main.go\", initialContent)\n   224→\tenv.GitAdd(\"main.go\")\n   225→\tenv.GitCommit(\"Initial commit\")\n   226→\n   227→\tenv.InitEntire()\n   228→\n   229→\t// ========================================\n   230→\t// CHECKPOINT 1: Agent REMOVES a function (deletion, no additions)\n   231→\t// ========================================\n   232→\tsession := env.NewSession()\n   233→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n   234→\t\tt.Fatalf(\"SimulateUserPromptSubmit failed: %v\", err)\n   235→\t}\n   236→\n   237→\t// Agent removes one function (keeps 2 functions)\n   238→\tcheckpointContent := \"package main\\n\\nfunc oldFunc2() {}\\nfunc oldFunc3() {}\\n\"\n   239→\tenv.WriteFile(\"main.go\", checkpointContent)\n   240→\n   241→\tsession.CreateTranscript(\n   242→\t\t\"Remove oldFunc1\",\n   243→\t\t[]FileChange{{Path: \"main.go\", Content: checkpointContent}},\n   244→\t)\n   245→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n   246→\t\tt.Fatalf(\"SimulateStop failed: %v\", err)\n   247→\t}\n   248→\n   249→\t// ========================================\n   250→\t// USER DELETES REMAINING FUNCTIONS\n   251→\t// ========================================\n   252→\tt.Log(\"User deletes remaining functions (deletion-only commit)\")\n   253→\n   254→\t// Remove remaining functions, keep only package declaration\n   255→\tenv.WriteFile(\"main.go\", \"package main\\n\")\n   256→\n   257→\t// Commit using hooks\n   258→\tenv.GitCommitWithShadowHooks(\"Remove remaining functions\", \"main.go\")\n   259→\n   260→\t// Get checkpoint ID\n   261→\theadHash := env.GetHeadHash()\n   262→\trepo, err := git.PlainOpen(env.RepoDir)\n   263→\tif err != nil {\n   264→\t\tt.Fatalf(\"failed to open repo: %v\", err)\n   265→\t}\n   266→\n   267→\tcommitObj, err := repo.CommitObject(plumbing.NewHash(headHash))\n   268→\tif err != nil {\n   269→\t\tt.Fatalf(\"failed to get commit object: %v\", err)\n   270→\t}\n   271→\n   272→\tcheckpointID, found := trailers.ParseCheckpoint(commitObj.Message)\n   273→\tif !found {\n   274→\t\tt.Fatal(\"Commit should have Entire-Checkpoint trailer\")\n   275→\t}\n   276→\n   277→\t// ========================================\n   278→\t// VERIFY ATTRIBUTION FOR DELETION-ONLY COMMIT\n   279→\t// ========================================\n   280→\tt.Log(\"Verifying attribution for deletion-only commit\")\n   281→\n   282→\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n   283→\tif err != nil {\n   284→\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n   285→\t}\n   286→\n   287→\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n   288→\tif err != nil {\n   289→\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n   290→\t}\n   291→\n   292→\tsessionsTree, err := sessionsCommit.Tree()\n   293→\tif err != nil {\n   294→\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n   295→\t}\n   296→\n   297→\t// Read session-level metadata.json (InitialAttribution is in 0/metadata.json)\n   298→\tmetadataPath := SessionMetadataPath(checkpointID.String())\n   299→\tmetadataFile, err := sessionsTree.File(metadataPath)\n   300→\tif err != nil {\n   301→\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n   302→\t}\n   303→\n   304→\tmetadataContent, err := metadataFile.Contents()\n   305→\tif err != nil {\n   306→\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n   307→\t}\n   308→\n   309→\tvar metadata checkpoint.CommittedMetadata\n   310→\tif err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {\n   311→\t\tt.Fatalf(\"Failed to parse metadata.json: %v\", err)\n   312→\t}\n   313→\n   314→\tif metadata.InitialAttribution == nil {\n   315→\t\tt.Fatal(\"InitialAttribution is nil\")\n   316→\t}\n   317→\n   318→\tattr := metadata.InitialAttribution\n   319→\tt.Logf(\"Attribution (deletion-only): agent=%d, human_added=%d, human_removed=%d, total=%d, percentage=%.1f%%\",\n   320→\t\tattr.AgentLines, attr.HumanAdded, attr.HumanRemoved,\n   321→\t\tattr.TotalCommitted, attr.AgentPercentage)\n   322→\n   323→\t// For deletion-only commits where agent makes no additions:\n   324→\t// - Agent removed oldFunc1 (made deletions, not additions)\n   325→\t// - AgentLines = 0 (no additions)\n   326→\t// - User removed oldFunc2 and oldFunc3\n   327→\t// - HumanAdded = 0 (no new lines)\n   328→\t// - HumanRemoved = number of lines user deleted\n   329→\t// - TotalCommitted = 0 (no additions from anyone)\n   330→\t// - AgentPercentage = 0 (by convention for deletion-only)\n   331→\n   332→\tif attr.AgentLines != 0 {\n   333→\t\tt.Errorf(\"AgentLines = %d, want 0 (agent made no additions, only deletions)\", attr.AgentLines)\n   334→\t}\n   335→\n   336→\tif attr.HumanAdded != 0 {\n   337→\t\tt.Errorf(\"HumanAdded = %d, want 0 (no new lines in deletion-only commit)\", attr.HumanAdded)\n   338→\t}\n   339→\n   340→\t// User removed 2 remaining functions + 1 blank line (3 lines total)\n   341→\tif attr.HumanRemoved != 3 {\n   342→\t\tt.Errorf(\"HumanRemoved = %d, want 3 (removed blank + 2 functions = 3 lines)\", attr.HumanRemoved)\n   343→\t}\n   344→\n   345→\tif attr.TotalCommitted != 0 {\n   346→\t\tt.Errorf(\"TotalCommitted = %d, want 0 (deletion-only commit has no net additions)\", attr.TotalCommitted)\n   347→\t}\n   348→\n   349→\tif attr.AgentPercentage != 0 {\n   350→\t\tt.Errorf(\"AgentPercentage = %.1f%%, want 0 (deletion-only commit)\",\n   351→\t\t\tattr.AgentPercentage)\n   352→\t}\n   353→}\n   354→\n   355→// TestManualCommit_AttributionNoDoubleCount tests that PromptAttributions are\n   356→// cleared after condensation to prevent double-counting on subsequent commits.\n   357→//\n   358→// Bug scenario:\n   359→// 1. Checkpoint 1 → user edits → commit (condensation, PromptAttributions used)\n   360→// 2. StepCount reset to 0, but PromptAttributions NOT cleared\n   361→// 3. Checkpoint 2 → new PromptAttributions appended to old ones\n   362→// 4. Second commit → CalculateAttributionWithAccumulated sums ALL PromptAttributions\n   363→// 5. User edits from first commit are double-counted\n   364→func TestManualCommit_AttributionNoDoubleCount(t *testing.T) {\n   365→\tt.Parallel()\n   366→\tenv := NewTestEnv(t)\n   367→\tdefer env.Cleanup()\n   368→\n   369→\tenv.InitRepo()\n   370→\n   371→\t// Create initial commit\n   372→\tenv.WriteFile(\"main.go\", \"package main\\n\")\n   373→\tenv.GitAdd(\"main.go\")\n   374→\tenv.GitCommit(\"Initial commit\")\n   375→\n   376→\tenv.InitEntire()\n   377→\n   378→\t// ========================================\n   379→\t// FIRST CYCLE: Checkpoint → user edit → commit\n   380→\t// ========================================\n   381→\tt.Log(\"First cycle: agent checkpoint + user edit + commit\")\n   382→\n   383→\tsession := env.NewSession()\n   384→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n   385→\t\tt.Fatalf(\"SimulateUserPromptSubmit (first cycle) failed: %v\", err)\n   386→\t}\n   387→\n   388→\t// Agent adds 5 lines\n   389→\tcheckpoint1Content := \"package main\\n\\nfunc agent1() { return 1 }\\nfunc agent2() { return 2 }\\nfunc agent3() { return 3 }\\n\"\n   390→\tenv.WriteFile(\"main.go\", checkpoint1Content)\n   391→\n   392→\tsession.CreateTranscript(\n   393→\t\t\"Add agent functions\",\n   394→\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint1Content}},\n   395→\t)\n   396→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n   397→\t\tt.Fatalf(\"SimulateStop (first cycle) failed: %v\", err)\n   398→\t}\n   399→\n   400→\t// User adds 2 lines between checkpoints\n   401→\tuserEdit1Content := checkpoint1Content + \"// User comment 1\\n// User comment 2\\n\"\n   402→\tenv.WriteFile(\"main.go\", userEdit1Content)\n   403→\n   404→\t// Commit with hooks (condensation happens)\n   405→\tenv.GitCommitWithShadowHooks(\"First commit\", \"main.go\")\n   406→\n   407→\t// Get first commit's checkpoint ID\n   408→\trepo, err := git.PlainOpen(env.RepoDir)\n   409→\tif err != nil {\n   410→\t\tt.Fatalf(\"failed to open repo: %v\", err)\n   411→\t}\n   412→\n   413→\thead, err := repo.Head()\n   414→\tif err != nil {\n   415→\t\tt.Fatalf(\"failed to get HEAD: %v\", err)\n   416→\t}\n   417→\n   418→\tcommit1, err := repo.CommitObject(head.Hash())\n   419→\tif err != nil {\n   420→\t\tt.Fatalf(\"failed to get commit: %v\", err)\n   421→\t}\n   422→\n   423→\tcheckpointID1, found := trailers.ParseCheckpoint(commit1.Message)\n   424→\tif !found {\n   425→\t\tt.Fatal(\"First commit should have checkpoint trailer\")\n   426→\t}\n   427→\n   428→\tt.Logf(\"First commit checkpoint ID: %s\", checkpointID1)\n   429→\n   430→\t// Verify first commit attribution\n   431→\tattr1 := getAttributionFromMetadata(t, repo, checkpointID1)\n   432→\tt.Logf(\"First commit attribution: agent=%d, human_added=%d, total=%d\",\n   433→\t\tattr1.AgentLines, attr1.HumanAdded, attr1.TotalCommitted)\n   434→\n   435→\t// First commit should have:\n   436→\t// - Agent: 4 lines (3 functions + 1 blank)\n   437→\t// - User: 2 lines (2 comments)\n   438→\t// - Total: 6 lines\n   439→\tif attr1.HumanAdded != 2 {\n   440→\t\tt.Errorf(\"First commit HumanAdded = %d, want 2\", attr1.HumanAdded)\n   441→\t}\n   442→\n   443→\t// ========================================\n   444→\t// SECOND CYCLE: New checkpoint → user edit → commit\n   445→\t// ========================================\n   446→\tt.Log(\"Second cycle: new agent checkpoint + user edit + commit\")\n   447→\n   448→\t// Simulate new prompt (should calculate attribution, which should be empty after reset)\n   449→\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n   450→\t\tt.Fatalf(\"SimulateUserPromptSubmit (second cycle) failed: %v\", err)\n   451→\t}\n   452→\n   453→\t// Agent adds 3 more lines\n   454→\tcheckpoint2Content := userEdit1Content + \"\\nfunc agent4() { return 4 }\\nfunc agent5() { return 5 }\\n\"\n   455→\tenv.WriteFile(\"main.go\", checkpoint2Content)\n   456→\n   457→\tsession.CreateTranscript(\n   458→\t\t\"Add more agent functions\",\n   459→\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint2Content}},\n   460→\t)\n   461→\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n   462→\t\tt.Fatalf(\"SimulateStop (second cycle) failed: %v\", err)\n   463→\t}\n   464→\n   465→\t// User adds 1 more line\n   466→\tuserEdit2Content := checkpoint2Content + \"// User comment 3\\n\"\n   467→\tenv.WriteFile(\"main.go\", userEdit2Content)\n   468→\n   469→\t// Second commit (another condensation)\n   470→\tenv.GitCommitWithShadowHooks(\"Second commit\", \"main.go\")\n   471→\n   472→\t// Get second commit's checkpoint ID\n   473→\thead, err = repo.Head()\n   474→\tif err != nil {\n   475→\t\tt.Fatalf(\"failed to get HEAD after second commit: %v\", err)\n   476→\t}\n   477→\n   478→\tcommit2, err := repo.CommitObject(head.Hash())\n   479→\tif err != nil {\n   480→\t\tt.Fatalf(\"failed to get second commit: %v\", err)\n   481→\t}\n   482→\n   483→\tcheckpointID2, found := trailers.ParseCheckpoint(commit2.Message)\n   484→\tif !found {\n   485→\t\tt.Fatal(\"Second commit should have checkpoint trailer\")\n   486→\t}\n   487→\n   488→\tt.Logf(\"Second commit checkpoint ID: %s\", checkpointID2)\n   489→\n   490→\t// Verify second commit attribution\n   491→\tattr2 := getAttributionFromMetadata(t, repo, checkpointID2)\n   492→\tt.Logf(\"Second commit attribution: agent=%d, human_added=%d, total=%d\",\n   493→\t\tattr2.AgentLines, attr2.HumanAdded, attr2.TotalCommitted)\n   494→\n   495→\t// Second commit should have (since first commit):\n   496→\t// - Agent: 3 lines (2 functions + 1 blank)\n   497→\t// - User: 1 line (1 comment)\n   498→\t// - Total: 4 lines\n   499→\t//\n   500→\t// BUG (if not fixed): HumanAdded would be 3 (1 new + 2 from first commit double-counted)\n   501→\t// CORRECT (after fix): HumanAdded should be 1 (only new user edits)\n   502→\n   503→\tif attr2.HumanAdded != 1 {\n   504→\t\tt.Errorf(\"Second commit HumanAdded = %d, want 1 (should NOT double-count first commit's 2 user lines)\",\n   505→\t\t\tattr2.HumanAdded)\n   506→\t}\n   507→\n   508→\tif attr2.TotalCommitted != 4 {\n   509→\t\tt.Errorf(\"Second commit TotalCommitted = %d, want 4 (3 agent + 1 user)\",\n   510→\t\t\tattr2.TotalCommitted)\n   511→\t}\n   512→\n   513→\t// Agent percentage should be 3/4 = 75%\n   514→\tif attr2.AgentPercentage < 74.9 || attr2.AgentPercentage > 75.1 {\n   515→\t\tt.Errorf(\"Second commit AgentPercentage = %.1f%%, want 75.0%%\", attr2.AgentPercentage)\n   516→\t}\n   517→}\n   518→\n   519→// getAttributionFromMetadata reads attribution from a checkpoint on entire/checkpoints/v1 branch.\n   520→// InitialAttribution is stored in session-level metadata (0/metadata.json).\n   521→func getAttributionFromMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) *checkpoint.InitialAttribution {\n   522→\tt.Helper()\n   523→\n   524→\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n   525→\tif err != nil {\n   526→\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n   527→\t}\n   528→\n   529→\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n   530→\tif err != nil {\n   531→\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n   532→\t}\n   533→\n   534→\tsessionsTree, err := sessionsCommit.Tree()\n   535→\tif err != nil {\n   536→\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n   537→\t}\n   538→\n   539→\t// Read session-level metadata (InitialAttribution is in 0/metadata.json)\n   540→\tmetadataPath := SessionMetadataPath(checkpointID.String())\n   541→\tmetadataFile, err := sessionsTree.File(metadataPath)\n   542→\tif err != nil {\n   543→\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n   544→\t}\n   545→\n   546→\tmetadataContent, err := metadataFile.Contents()\n   547→\tif err != nil {\n   548→\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n   549→\t}\n   550→\n   551→\tvar metadata checkpoint.CommittedMetadata\n   552→\tif err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {\n   553→\t\tt.Fatalf(\"Failed to parse metadata.json: %v\", err)\n   554→\t}\n   555→\n   556→\tif metadata.InitialAttribution == nil {\n   557→\t\tt.Fatal(\"InitialAttribution is nil\")\n   558→\t}\n   559→\n   560→\treturn metadata.InitialAttribution\n   561→}\n   562→"}]},"uuid":"b03423f7-7516-4eb2-9f72-d15eee6ffe56","timestamp":"2026-03-27T08:48:01.427Z","toolUseResult":{"type":"text","file":{"filePath":"/repo/cli/cmd/entire/cli/integration_test/attribution_test.go","content":"//go:build integration\n\npackage integration\n\nimport (\n\t\"encoding/json\"\n\t\"testing\"\n\n\t\"github.com/entireio/cli/cmd/entire/cli/checkpoint\"\n\t\"github.com/entireio/cli/cmd/entire/cli/checkpoint/id\"\n\t\"github.com/entireio/cli/cmd/entire/cli/paths\"\n\t\"github.com/entireio/cli/cmd/entire/cli/trailers\"\n\t\"github.com/go-git/go-git/v6\"\n\t\"github.com/go-git/go-git/v6/plumbing\"\n)\n\n// TestManualCommit_Attribution tests the full attribution calculation flow:\n// 1. Agent creates checkpoint 1\n// 2. User makes changes between checkpoints\n// 3. User enters new prompt (attribution calculated at prompt start)\n// 4. Agent creates checkpoint 2\n// 5. User commits (condensation happens with attribution)\n// 6. Verify attribution metadata is correct\nfunc TestManualCommit_Attribution(t *testing.T) {\n\tt.Parallel()\n\tenv := NewTestEnv(t)\n\tdefer env.Cleanup()\n\n\tenv.InitRepo()\n\n\t// Create initial commit\n\tenv.WriteFile(\"main.go\", \"package main\\n\")\n\tenv.GitAdd(\"main.go\")\n\tenv.GitCommit(\"Initial commit\")\n\n\tenv.InitEntire()\n\n\tinitialHead := env.GetHeadHash()\n\tt.Logf(\"Initial HEAD: %s\", initialHead[:7])\n\n\t// ========================================\n\t// CHECKPOINT 1: Agent adds function\n\t// ========================================\n\tt.Log(\"Creating checkpoint 1 (agent adds function)\")\n\n\tsession := env.NewSession()\n\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n\t\tt.Fatalf(\"SimulateUserPromptSubmit (prompt 1) failed: %v\", err)\n\t}\n\n\t// Agent adds 4 lines\n\tcheckpoint1Content := \"package main\\n\\nfunc agentFunc() {\\n\\treturn 42\\n}\\n\"\n\tenv.WriteFile(\"main.go\", checkpoint1Content)\n\n\tsession.CreateTranscript(\n\t\t\"Add agent function\",\n\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint1Content}},\n\t)\n\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n\t\tt.Fatalf(\"SimulateStop (checkpoint 1) failed: %v\", err)\n\t}\n\n\t// ========================================\n\t// USER EDITS between checkpoints\n\t// ========================================\n\tt.Log(\"User makes edits between checkpoints\")\n\n\t// User adds 5 comment lines\n\tuserContent := checkpoint1Content +\n\t\t\"// User comment 1\\n\" +\n\t\t\"// User comment 2\\n\" +\n\t\t\"// User comment 3\\n\" +\n\t\t\"// User comment 4\\n\" +\n\t\t\"// User comment 5\\n\"\n\tenv.WriteFile(\"main.go\", userContent)\n\n\t// ========================================\n\t// CHECKPOINT 2: New prompt (attribution calculated)\n\t// ========================================\n\tt.Log(\"User enters new prompt (attribution should capture 5 user lines)\")\n\n\t// Simulate UserPromptSubmit hook - this calculates attribution at prompt start\n\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n\t\tt.Fatalf(\"SimulateUserPromptSubmit (prompt 2) failed: %v\", err)\n\t}\n\n\t// Agent adds another function (4 more lines)\n\tcheckpoint2Content := userContent + \"\\nfunc agentFunc2() {\\n\\treturn 100\\n}\\n\"\n\tenv.WriteFile(\"main.go\", checkpoint2Content)\n\n\tsession.CreateTranscript(\n\t\t\"Add second agent function\",\n\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint2Content}},\n\t)\n\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n\t\tt.Fatalf(\"SimulateStop (checkpoint 2) failed: %v\", err)\n\t}\n\n\t// Verify 2 rewind points\n\tpoints := env.GetRewindPoints()\n\tif len(points) != 2 {\n\t\tt.Fatalf(\"Expected 2 rewind points, got %d\", len(points))\n\t}\n\n\t// ========================================\n\t// USER COMMITS: Condensation happens\n\t// ========================================\n\tt.Log(\"User commits (condensation should happen)\")\n\n\t// Commit using hooks (this triggers condensation)\n\tenv.GitCommitWithShadowHooks(\"Add functions\", \"main.go\")\n\n\t// Get commit hash and checkpoint ID\n\theadHash := env.GetHeadHash()\n\tt.Logf(\"User commit: %s\", headHash[:7])\n\n\trepo, err := git.PlainOpen(env.RepoDir)\n\tif err != nil {\n\t\tt.Fatalf(\"failed to open repo: %v\", err)\n\t}\n\n\tcommitObj, err := repo.CommitObject(plumbing.NewHash(headHash))\n\tif err != nil {\n\t\tt.Fatalf(\"failed to get commit object: %v\", err)\n\t}\n\n\tcheckpointID, found := trailers.ParseCheckpoint(commitObj.Message)\n\tif !found {\n\t\tt.Fatal(\"Commit should have Entire-Checkpoint trailer\")\n\t}\n\tt.Logf(\"Checkpoint ID: %s\", checkpointID)\n\n\t// ========================================\n\t// VERIFY ATTRIBUTION\n\t// ========================================\n\tt.Log(\"Verifying attribution in metadata\")\n\n\t// Read metadata from entire/checkpoints/v1 branch\n\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n\t}\n\n\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n\t}\n\n\tsessionsTree, err := sessionsCommit.Tree()\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n\t}\n\n\t// Read session-level metadata.json from sharded path (InitialAttribution is in 0/metadata.json)\n\tmetadataPath := SessionMetadataPath(checkpointID.String())\n\tmetadataFile, err := sessionsTree.File(metadataPath)\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n\t}\n\n\tmetadataContent, err := metadataFile.Contents()\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n\t}\n\n\tvar metadata checkpoint.CommittedMetadata\n\tif err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {\n\t\tt.Fatalf(\"Failed to parse metadata.json: %v\", err)\n\t}\n\n\t// Verify InitialAttribution exists\n\tif metadata.InitialAttribution == nil {\n\t\tt.Fatal(\"InitialAttribution is nil\")\n\t}\n\n\tattr := metadata.InitialAttribution\n\tt.Logf(\"Attribution: agent=%d, human_added=%d, human_modified=%d, human_removed=%d, total=%d, percentage=%.1f%%\",\n\t\tattr.AgentLines, attr.HumanAdded, attr.HumanModified, attr.HumanRemoved,\n\t\tattr.TotalCommitted, attr.AgentPercentage)\n\n\t// Verify attribution was calculated and has reasonable values\n\t// Note: The shadow branch includes all worktree changes (agent + user),\n\t// so base→shadow diff includes user edits that were present during SaveStep.\n\t// The attribution separates them using PromptAttributions.\n\t//\n\t// Expected: agent=13 (base→shadow includes user comments in worktree)\n\t//           human=5 (from PromptAttribution)\n\t//           total=18 (net additions)\n\t//\n\t// This tests that:\n\t// 1. Attribution is calculated and stored\n\t// 2. PromptAttribution captured user edits between checkpoints\n\t// 3. Percentages are computed\n\tif attr.AgentLines <= 0 {\n\t\tt.Errorf(\"AgentLines = %d, should be > 0\", attr.AgentLines)\n\t}\n\n\tif attr.HumanAdded != 5 {\n\t\tt.Errorf(\"HumanAdded = %d, want 5 (5 comments captured in PromptAttribution)\",\n\t\t\tattr.HumanAdded)\n\t}\n\n\tif attr.TotalCommitted <= 0 {\n\t\tt.Errorf(\"TotalCommitted = %d, should be > 0\", attr.TotalCommitted)\n\t}\n\n\tif attr.AgentPercentage <= 0 || attr.AgentPercentage >= 100 {\n\t\tt.Errorf(\"AgentPercentage = %.1f%%, should be between 0 and 100\",\n\t\t\tattr.AgentPercentage)\n\t}\n}\n\n// TestManualCommit_AttributionDeletionOnly tests attribution for deletion-only commits\nfunc TestManualCommit_AttributionDeletionOnly(t *testing.T) {\n\tt.Parallel()\n\tenv := NewTestEnv(t)\n\tdefer env.Cleanup()\n\n\tenv.InitRepo()\n\n\t// Create initial commit with content\n\tinitialContent := \"package main\\n\\nfunc oldFunc1() {}\\nfunc oldFunc2() {}\\nfunc oldFunc3() {}\\n\"\n\tenv.WriteFile(\"main.go\", initialContent)\n\tenv.GitAdd(\"main.go\")\n\tenv.GitCommit(\"Initial commit\")\n\n\tenv.InitEntire()\n\n\t// ========================================\n\t// CHECKPOINT 1: Agent REMOVES a function (deletion, no additions)\n\t// ========================================\n\tsession := env.NewSession()\n\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n\t\tt.Fatalf(\"SimulateUserPromptSubmit failed: %v\", err)\n\t}\n\n\t// Agent removes one function (keeps 2 functions)\n\tcheckpointContent := \"package main\\n\\nfunc oldFunc2() {}\\nfunc oldFunc3() {}\\n\"\n\tenv.WriteFile(\"main.go\", checkpointContent)\n\n\tsession.CreateTranscript(\n\t\t\"Remove oldFunc1\",\n\t\t[]FileChange{{Path: \"main.go\", Content: checkpointContent}},\n\t)\n\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n\t\tt.Fatalf(\"SimulateStop failed: %v\", err)\n\t}\n\n\t// ========================================\n\t// USER DELETES REMAINING FUNCTIONS\n\t// ========================================\n\tt.Log(\"User deletes remaining functions (deletion-only commit)\")\n\n\t// Remove remaining functions, keep only package declaration\n\tenv.WriteFile(\"main.go\", \"package main\\n\")\n\n\t// Commit using hooks\n\tenv.GitCommitWithShadowHooks(\"Remove remaining functions\", \"main.go\")\n\n\t// Get checkpoint ID\n\theadHash := env.GetHeadHash()\n\trepo, err := git.PlainOpen(env.RepoDir)\n\tif err != nil {\n\t\tt.Fatalf(\"failed to open repo: %v\", err)\n\t}\n\n\tcommitObj, err := repo.CommitObject(plumbing.NewHash(headHash))\n\tif err != nil {\n\t\tt.Fatalf(\"failed to get commit object: %v\", err)\n\t}\n\n\tcheckpointID, found := trailers.ParseCheckpoint(commitObj.Message)\n\tif !found {\n\t\tt.Fatal(\"Commit should have Entire-Checkpoint trailer\")\n\t}\n\n\t// ========================================\n\t// VERIFY ATTRIBUTION FOR DELETION-ONLY COMMIT\n\t// ========================================\n\tt.Log(\"Verifying attribution for deletion-only commit\")\n\n\tsessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to get entire/checkpoints/v1 branch: %v\", err)\n\t}\n\n\tsessionsCommit, err := repo.CommitObject(sessionsRef.Hash())\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to get sessions commit: %v\", err)\n\t}\n\n\tsessionsTree, err := sessionsCommit.Tree()\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to get sessions tree: %v\", err)\n\t}\n\n\t// Read session-level metadata.json (InitialAttribution is in 0/metadata.json)\n\tmetadataPath := SessionMetadataPath(checkpointID.String())\n\tmetadataFile, err := sessionsTree.File(metadataPath)\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to read session metadata.json at path %s: %v\", metadataPath, err)\n\t}\n\n\tmetadataContent, err := metadataFile.Contents()\n\tif err != nil {\n\t\tt.Fatalf(\"Failed to read metadata content: %v\", err)\n\t}\n\n\tvar metadata checkpoint.CommittedMetadata\n\tif err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {\n\t\tt.Fatalf(\"Failed to parse metadata.json: %v\", err)\n\t}\n\n\tif metadata.InitialAttribution == nil {\n\t\tt.Fatal(\"InitialAttribution is nil\")\n\t}\n\n\tattr := metadata.InitialAttribution\n\tt.Logf(\"Attribution (deletion-only): agent=%d, human_added=%d, human_removed=%d, total=%d, percentage=%.1f%%\",\n\t\tattr.AgentLines, attr.HumanAdded, attr.HumanRemoved,\n\t\tattr.TotalCommitted, attr.AgentPercentage)\n\n\t// For deletion-only commits where agent makes no additions:\n\t// - Agent removed oldFunc1 (made deletions, not additions)\n\t// - AgentLines = 0 (no additions)\n\t// - User removed oldFunc2 and oldFunc3\n\t// - HumanAdded = 0 (no new lines)\n\t// - HumanRemoved = number of lines user deleted\n\t// - TotalCommitted = 0 (no additions from anyone)\n\t// - AgentPercentage = 0 (by convention for deletion-only)\n\n\tif attr.AgentLines != 0 {\n\t\tt.Errorf(\"AgentLines = %d, want 0 (agent made no additions, only deletions)\", attr.AgentLines)\n\t}\n\n\tif attr.HumanAdded != 0 {\n\t\tt.Errorf(\"HumanAdded = %d, want 0 (no new lines in deletion-only commit)\", attr.HumanAdded)\n\t}\n\n\t// User removed 2 remaining functions + 1 blank line (3 lines total)\n\tif attr.HumanRemoved != 3 {\n\t\tt.Errorf(\"HumanRemoved = %d, want 3 (removed blank + 2 functions = 3 lines)\", attr.HumanRemoved)\n\t}\n\n\tif attr.TotalCommitted != 0 {\n\t\tt.Errorf(\"TotalCommitted = %d, want 0 (deletion-only commit has no net additions)\", attr.TotalCommitted)\n\t}\n\n\tif attr.AgentPercentage != 0 {\n\t\tt.Errorf(\"AgentPercentage = %.1f%%, want 0 (deletion-only commit)\",\n\t\t\tattr.AgentPercentage)\n\t}\n}\n\n// TestManualCommit_AttributionNoDoubleCount tests that PromptAttributions are\n// cleared after condensation to prevent double-counting on subsequent commits.\n//\n// Bug scenario:\n// 1. Checkpoint 1 → user edits → commit (condensation, PromptAttributions used)\n// 2. StepCount reset to 0, but PromptAttributions NOT cleared\n// 3. Checkpoint 2 → new PromptAttributions appended to old ones\n// 4. Second commit → CalculateAttributionWithAccumulated sums ALL PromptAttributions\n// 5. User edits from first commit are double-counted\nfunc TestManualCommit_AttributionNoDoubleCount(t *testing.T) {\n\tt.Parallel()\n\tenv := NewTestEnv(t)\n\tdefer env.Cleanup()\n\n\tenv.InitRepo()\n\n\t// Create initial commit\n\tenv.WriteFile(\"main.go\", \"package main\\n\")\n\tenv.GitAdd(\"main.go\")\n\tenv.GitCommit(\"Initial commit\")\n\n\tenv.InitEntire()\n\n\t// ========================================\n\t// FIRST CYCLE: Checkpoint → user edit → commit\n\t// ========================================\n\tt.Log(\"First cycle: agent checkpoint + user edit + commit\")\n\n\tsession := env.NewSession()\n\tif err := env.SimulateUserPromptSubmit(session.ID); err != nil {\n\t\tt.Fatalf(\"SimulateUserPromptSubmit (first cycle) failed: %v\", err)\n\t}\n\n\t// Agent adds 5 lines\n\tcheckpoint1Content := \"package main\\n\\nfunc agent1() { return 1 }\\nfunc agent2() { return 2 }\\nfunc agent3() { return 3 }\\n\"\n\tenv.WriteFile(\"main.go\", checkpoint1Content)\n\n\tsession.CreateTranscript(\n\t\t\"Add agent functions\",\n\t\t[]FileChange{{Path: \"main.go\", Content: checkpoint1Content}},\n\t)\n\tif err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {\n\t\tt.Fatalf(\"SimulateStop (first cycle) failed: %v\", err)\n\t}\n\n\t// User adds 2 lines between checkpoints\n\tuserEdit1Content := checkpoint1Content + \"// User comment 1\\n// User comment 2\\n\"\n\tenv.WriteFile(\"main.go\", userEdit1Content)\n\n\t// Commit with hooks (condensation happens)\n\tenv.GitCommitWithShadowHooks(\"First commit\", \"main.go\")\n\n\t// Get first commit's checkpoint ID\n\trepo, err := git.PlainOpen(env.RepoDir)\n\tif err != nil {\n\t\tt.Fatalf(\"failed to open repo: %v\", err)\n\t}\n\n\thead, err := repo.Head()\n\tif err != nil {\n\t\tt.Fatalf(\"failed to get HEAD: %v\", err)\n\t}\n\n\tcommit1, err := repo.CommitObject(head.Hash())\n\tif err != nil {\n\t\tt.Fatalf(\"failed to get commit: %v\", err)\n\t}\n\n\tcheckpointID1, found := trailers.ParseCheckpoint(commit1.Message)\n\tif !found {\n\t\tt.Fatal(\"First commit should have checkpoint trailer\")\n\t}\n\n\tt.Logf(\"First commit checkpoint ID: %s\", checkpointID1)\n\n\t// Verify first commit attribution\n\tattr1 := getAttributionFromMetadata(t, repo, checkpointID1)\n\tt.Logf(\"First commit attribution: agent=%d, human_added=%d, total=%d\",\n\t\tattr1.AgentLines, attr1.HumanAdded, attr1.TotalCommitted)\n\n\t// First commit should have:\n\t// - Agent: 4 lines (3 functions + 1 blank)\n\t// - User: 2 lines (2 comments)\n\t// - Total: 6 lines\n\tif attr1.HumanAdded != 2 {\n\t\tt.Errorf(\"First commit