t only adds agent lines to main.go.","+  // utils.go (50 lines) was committed BEFORE the second cycle.","+  //","+  // CORRECT (AttributionBaseCommit = unrelated commit):","+  //   human_added = 0, agent_lines ≈ 3-4, agent_percentage = 100%","+  //","+  // BUG (AttributionBaseCommit = first commit, stale):","+  //   human_added = 50+ (utils.go lines incorrectly counted as user work)","+  //   agent_percentage ≈ 6% (inflated denominator)","+","+  if attr2.HumanAdded != 0 {","+    t.Errorf(\"HumanAdded = %d, want 0 (utils.go was committed before this cycle; stale AttributionBaseCommit?)\",","+      attr2.HumanAdded)","+  }","+","+  if attr2.AgentLines <= 0 {","+    t.Errorf(\"AgentLines = %d, should be > 0\", attr2.AgentLines)","+  }","+","+  if attr2.AgentPercentage != 100 {","+    t.Errorf(\"AgentPercentage = %.1f%%, want 100%% (only agent lines in this commit)\",","+      attr2.AgentPercentage)","+  }","+}","+"," // getAttributionFromMetadata reads attribution from a checkpoint on entire/checkpoints/v1 branch."," // InitialAttribution is stored in session-level metadata (0/metadata.json)."," func getAttributionFromMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID) *checkpoint.InitialAttribution {"]}],"userModified":false,"replaceAll":false},"sourceToolAssistantUUID":"73375918-9694-418e-8c37-fa4c3e199328","userType":"external","entrypoint":"cli","cwd":"/repo/cli","sessionId":"466e2cb2-1cca-4296-8efd-ef4bb139d9c3","version":"2.1.85","gitBranch":"main","slug":"gentle-wishing-ladybug"}
