t\theadContent := getFileContent(headTree, filePath)\n   263→\t\t_, userAdded, _ := diffLines(baseContent, headContent)\n   264→\t\tallUserEditsToNonAgentFiles += userAdded\n   265→\t}\n   266→\n   267→\t// Separate accumulated edits by file type using per-file tracking data.\n   268→\t// Only count changes to files that are actually committed:\n   269→\t// - Agent-touched files (filesTouched)\n   270→\t// - Non-agent files that appear in the commit (base→head diff)\n   271→\t// Files not in either set are worktree-only changes (e.g., .claude/settings.json)\n   272→\t// that should not affect attribution.\n   273→\tcommittedNonAgentSet := make(map[string]struct{}, len(allChangedFiles))\n   274→\tfor _, f := range allChangedFiles {\n   275→\t\tif !slices.Contains(filesTouched, f) {\n   276→\t\t\tcommittedNonAgentSet[f] = struct{}{}\n   277→\t\t}\n   278→\t}\n   279→\n   280→\tvar accumulatedToAgentFiles, accumulatedToCommittedNonAgentFiles int\n   281→\tfor filePath, added := range accumulatedUserAddedPerFile {\n   282→\t\tif slices.Contains(filesTouched, filePath) {\n   283→\t\t\taccumulatedToAgentFiles += added\n   284→\t\t} else if _, ok := committedNonAgentSet[filePath]; ok {\n   285→\t\t\taccumulatedToCommittedNonAgentFiles += added\n   286→\t\t}\n   287→\t\t// else: file not committed (worktree-only), excluded from attribution\n   288→\t}\n   289→\n   290→\t// Agent work = (base→shadow for agent files) - (accumulated user edits to agent files only)\n   291→\ttotalAgentAdded := max(0, totalAgentAndUserWork-accumulatedToAgentFiles)\n   292→\n   293→\t// Post-checkpoint edits to non-agent files = total edits - accumulated portion (never negative)\n   294→\tpostToNonAgentFiles := max(0, allUserEditsToNonAgentFiles-accumulatedToCommittedNonAgentFiles)\n   295→\n   296→\t// Total user contribution = accumulated (committed files only) + post-checkpoint edits\n   297→\trelevantAccumulatedUser := accumulatedToAgentFiles + accumulatedToCommittedNonAgentFiles\n   298→\ttotalUserAdded := relevantAccumulatedUser + postCheckpointUserAdded + postToNonAgentFiles\n   299→\t// TODO: accumulatedUserRemoved also includes removals from uncommitted files,\n   300→\t// but we don't have per-file tracking for removals yet. In practice, removals\n   301→\t// from uncommitted files are rare and the impact is minor (could slightly reduce\n   302→\t// totalCommitted via pureUserRemoved). Add UserRemovedPerFile if this becomes an issue.\n   303→\ttotalUserRemoved := accumulatedUserRemoved + postCheckpointUserRemoved\n   304→\n   305→\t// Estimate modified lines (user changed existing lines)\n   306→\t// Lines that were both added and removed are treated as modifications.\n   307→\ttotalHumanModified := min(totalUserAdded, totalUserRemoved)\n   308→\n   309→\t// Estimate user self-modifications using per-file tracking (see docs/architecture/attribution.md)\n   310→\t// When a user removes lines from a file, assume they're removing their own lines first (LIFO).\n   311→\t// Only after exhausting their own additions should we count removals as targeting agent lines.\n   312→\tuserSelfModified := estimateUserSelfModifications(accumulatedUserAddedPerFile, postCheckpointUserRemovedPerFile)\n   313→\n   314→\t// humanModifiedAgent = modifications that targeted agent lines (not user's own lines)\n   315→\thumanModifiedAgent := max(0, totalHumanModified-userSelfModified)\n   316→\n   317→\t// Remaining modifications are user self-modifications (user edited their own code)\n   318→\t// These should NOT be subtracted from agent lines\n   319→\tpureUserAdded := totalUserAdded - totalHumanModified\n   320→\tpureUserRemoved := totalUserRemoved - totalHumanModified\n   321→\n   322→\t// Total net additions = agent additions + pure user additions - pure user removals\n   323→\t// This reconstructs the base → head diff from our tracked changes.\n   324→\t// Note: This measures \"net new lines added to the codebase\" not total file size.\n   325→\t// pureUserRemoved represents agent lines that the user deleted, so we subtract them.\n   326→\ttotalCommitted := totalAgentAdded + pureUserAdded - pureUserRemoved\n   327→\tif totalCommitted \u003c= 0 {\n   328→\t\t// Fallback for delete-only commits or when removals exceed additions\n   329→\t\t// Note: If both are 0 (deletion-only commit where agent added nothing),\n   330→\t\t// totalCommitted will be 0 and percentage will be 0. This is expected -\n   331→\t\t// the attribution percentage is only meaningful for commits that add code.\n   332→\t\ttotalCommitted = max(0, totalAgentAdded)\n   333→\t}\n   334→\n   335→\t// Calculate agent lines actually in the commit (excluding removed and modified)\n   336→\t// Agent added lines, but user removed some and modified others.\n   337→\t// Only subtract modifications that targeted AGENT lines (humanModifiedAgent),\n   338→\t// not user self-modifications.\n   339→\t// Clamp to 0 to handle cases where user removed/modified more than agent added.\n   340→\tagentLinesInCommit := max(0, totalAgentAdded-pureUserRemoved-humanModifiedAgent)\n   341→\n   342→\t// Calculate percentage\n   343→\tvar agentPercentage float64\n   344→\tif totalCommitted \u003e 0 {\n   345→\t\tagentPercentage = float64(agentLinesInCommit) / float64(totalCommitted) * 100\n   346→\t}\n   347→\n   348→\treturn \u0026checkpoint.InitialAttribution{\n   349→\t\tCalculatedAt:    time.Now().UTC(),\n   350→\t\tAgentLines:      agentLinesInCommit,\n   351→\t\tHumanAdded:      pureUserAdded,\n   352→\t\tHumanModified:   totalHumanModified, // Total modifications (for reporting)\n   353→\t\tHumanRemoved:    pureUserRemoved,\n   354→\t\tTotalCommitted:  totalCommitted,\n   355→\t\tAgentPercentage: agentPercentage,\n   356→\t}\n   357→}\n   358→\n   359→// estimateUserSelfModifications estimates how many removed lines were the user's own additions.\n   360→// Uses LIFO assumption: when a user removes lines from a file, they likely remove their own\n   361→// recent additions before touching agent lines.\n   362→//\n   363→// See docs/architecture/attribution.md for the rationale behind this heuristic.\n   364→func estimateUserSelfModifications(\n   365→\taccumulatedUserAddedPerFile map[string]int,\n   366→\tpostCheckpointUserRemovedPerFile map[string]int,\n   367→) int {\n   368→\tvar selfModified int\n   369→\tfor filePath, removed := range postCheckpointUserRemovedPerFile {\n   370→\t\tuserAddedToFile := accumulatedUserAddedPerFile[filePath]\n   371→\t\t// User can only self-modify up to what they previously added\n   372→\t\tselfModified += min(removed, userAddedToFile)\n   373→\t}\n   374→\treturn selfModified\n   375→}\n   376→\n   377→// CalculatePromptAttribution computes line-level attribution at the start of a prompt.\n   378→// This captures user edits since the last checkpoint BEFORE the agent makes changes.\n   379→//\n   380→// Parameters:\n   381→//   - baseTree: the tree at session start (the base commit)\n   382→//   - lastCheckpointTree: the tree from the previous checkpoint (nil if first checkpoint)\n   383→//   - worktreeFiles: map of file path → current worktree content for files that changed\n   384→//   - checkpointNumber: which checkpoint we're about to create (1-indexed)\n   385→//\n   386→// Returns the attribution data to store in session state. For checkpoint 1 (when\n   387→// lastCheckpointTree is nil), AgentLinesAdded/Removed will be 0 since there's no\n   388→// previous checkpoint to measure cumulative agent work against.\n   389→//\n   390→// Note: Binary files (detected by null bytes) in reference trees are silently excluded\n   391→// from attribution calculations since line-based diffing only applies to text files.\n   392→func CalculatePromptAttribution(\n   393→\tbaseTree *object.Tree,\n   394→\tlastCheckpointTree *object.Tree,\n   395→\tworktreeFiles map[string]string,\n   396→\tcheckpointNumber int,\n   397→) PromptAttribution {\n   398→\tresult := PromptAttribution{\n   399→\t\tCheckpointNumber: checkpointNumber,\n   400→\t\tUserAddedPerFile: make(map[string]int),\n   401→\t}\n   402→\n   403→\tif len(worktreeFiles) == 0 {\n   404→\t\treturn result\n   405→\t}\n   406→\n   407→\t// Determine reference tree for user changes (last checkpoint or base)\n   408→\treferenceTree := lastCheckpointTree\n   409→\tif referenceTree == nil {\n   410→\t\treferenceTree = baseTree\n   411→\t}\n   412→\n   413→\tfor filePath, worktreeContent := range worktreeFiles {\n   414→\t\treferenceContent := getFileContent(referenceTree, filePath)\n   415→\t\tbaseContent := getFileContent(baseTree, filePath)\n   416→\n   417→\t\t// User changes: diff(reference, worktree)\n   418→\t\t// These are changes since the last checkpoint that the agent didn't make\n   419→\t\t_, userAdded, userRemoved := diffLines(referenceContent, worktreeContent)\n   420→\t\tresult.UserLinesAdded += userAdded\n   421→\t\tresult.UserLinesRemoved += userRemoved\n   422→\n   423→\t\t// Track per-file user additions for accurate modification tracking.\n   424→\t\t// This enables distinguishing user self-modifications from agent modifications.\n   425→\t\tif userAdded \u003e 0 {\n   426→\t\t\tresult.UserAddedPerFile[filePath] = userAdded\n   427→\t\t}\n   428→\n   429→\t\t// Agent lines so far: diff(base, lastCheckpoint)\n   430→\t\t// Only calculate if we have a previous checkpoint\n   431→\t\tif lastCheckpointTree != nil {\n   432→\t\t\tcheckpointContent := getFileContent(lastCheckpointTree, filePath)\n   433→\t\t\t_, agentAdded, agentRemoved := diffLines(baseContent, checkpointContent)\n   434→\t\t\tresult.AgentLinesAdded += agentAdded\n   435→\t\t\tresult.AgentLinesRemoved += agentRemoved\n   436→\t\t}\n   437→\t}\n   438→\n   439→\treturn result\n   440→}\n   441→","status":"success","file":{"filePath":"/repo/cli/cmd/entire/cli/strategy/manual_commit_attribution.go","numLines":441}},"type":"tool_use"}]}
