		CacheReadTokens:     clampSubtract(a.CacheReadTokens, b.CacheReadTokens),
		OutputTokens:        clampSubtract(a.OutputTokens, b.OutputTokens),
		APICallCount:        clampSubtract(a.APICallCount, b.APICallCount),
