	ctx, err := Builder{Reader: testReader(), Repo: repo, RepoRoot: repoRoot}.Build(context.Background(), testCheckpointID)
	if err != nil {
		t.Fatalf("Build() error = %v", err)
	}
	if len(ctx.Git.AssociatedCommits) != 1 {
		t.Fatalf("AssociatedCommits = %+v", ctx.Git.AssociatedCommits)
	}
	if ctx.Git.AssociatedCommits[0].Source != "commit_trailer" {
		t.Fatalf("Source = %q", ctx.Git.AssociatedCommits[0].Source)
	}
	if !strings.Contains(ctx.Git.Diff, "feature.go") {
		t.Fatalf("GitDiff missing feature.go:\n%s", ctx.Git.Diff)
	}
	if len(ctx.ChangedFiles) != 1 || ctx.ChangedFiles[0].Path != "feature.go" {
		t.Fatalf("ChangedFiles = %+v", ctx.ChangedFiles)
	}
}

func TestBuildGraphUnavailableDoesNotBreakContext(t *testing.T) {
	ctx, err := Builder{Reader: testReader()}.Build(context.Background(), testCheckpointID)
	if err != nil {
		t.Fatalf("Build() error = %v", err)
	}
	if ctx.Graph.Available {
		t.Fatal("Graph.Available = true, want false")
	}
	if ctx.Graph.UnavailableReason == "" {
		t.Fatal("Graph.UnavailableReason is empty")
	}
}

func TestBuildMissingCheckpointReturnsClearError(t *testing.T) {
	_, err := Builder{Reader: fakeReader{summary: nil}}.Build(context.Background(), testCheckpointID)
	if err == nil {
		t.Fatal("Build() error = nil, want error")
	}
	if !strings.Contains(err.Error(), "read checkpoint") {
		t.Fatalf("error = %v, want read checkpoint context", err)
	}
}

func TestBuildDoesNotFabricateUnavailableData(t *testing.T) {
	reader := testReader()
	reader.sessions[0].Transcript = nil
	reader.sessions[1].Transcript = nil
	ctx, err := Builder{Reader: reader}.Build(context.Background(), testCheckpointID)
	if err != nil {
		t.Fatalf("Build() error = %v", err)
	}
	if ctx.Transcript.Available {
		t.Fatal("Transcript.Available = true, want false")
	}
	if len(ctx.Git.AssociatedCommits) != 0 || ctx.Git.Diff != "" {
		t.Fatalf("git evidence fabricated: %+v", ctx.Git)
	}
	if len(ctx.TaskRecords) != 0 {
		t.Fatalf("TaskRecords = %+v, want none", ctx.TaskRecords)
	}
}

func testReader() fakeReader {
	now := time.Date(2026, 9, 6, 10, 0, 0, 0, time.UTC)
	return fakeReader{
		summary: &checkpoint.CheckpointSummary{
			CheckpointID:     testCheckpointID,
			Strategy:         "manual-commit",
			Branch:           "main",
			CheckpointsCount: 2,
			FilesTouched:     []string{"feature_test.go", "feature.go"},
			Sessions:         []checkpoint.SessionFilePaths{{}, {}},
			TokenUsage:       &types.TokenUsage{InputTokens: 21, OutputTokens: 13},
		},
		sessions: []*checkpoint.SessionContent{
			{
				Metadata: checkpoint.Metadata{
					CheckpointID:     testCheckpointID,
					SessionID:        "session-1",
					CreatedAt:        now,
					Strategy:         "manual-commit",
					Branch:           "main",
					CheckpointsCount: 1,
					SaveStepCount:    1,
					FilesTouched:     []string{"feature.go"},
					Agent:            types.AgentTypeCodex,
					Model:            "gpt-test",
					TokenUsage:       &types.TokenUsage{InputTokens: 11, OutputTokens: 7},
				},
				Transcript: []byte(`{"type":"response_item"}`),
				Prompts: "Implement Google OAuth login.\nDo NOT modify the database schema." + checkpoint.PromptSeparator + "Keep it minimal.",
			},
			{
				Metadata: checkpoint.Metadata{
					CheckpointID:     testCheckpointID,
					SessionID:        "session-2",
					CreatedAt:        now.Add(time.Minute),
					Strategy:         "manual-commit",
					FilesTouched:     []string{"feature_test.go"},
					Agent:            types.AgentTypeCodex,
					Model:            "gpt-test",
				},
				Transcript: []byte(`{"type":"response_item"}`),
				Prompts:    "Add focused tests.",
			},
		},
	}
}

func repoWithCheckpointCommit(t *testing.T, cpID id.CheckpointID) (string, *git.Repository) {
	t.Helper()
	dir := t.TempDir()
	runGit(t, dir, "init")
	runGit(t, dir, "config", "user.name", "Test User")
	runGit(t, dir, "config", "user.email", "test@example.com")
	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("init\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runGit(t, dir, "add", "README.md")
	runGit(t, dir, "commit", "-m", "init")
	if err := os.WriteFile(filepath.Join(dir, "feature.go"), []byte("package feature\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runGit(t, dir, "add", "feature.go")
	runGit(t, dir, "commit", "-m", "add feature\n\nEntire-Checkpoint: "+cpID.String())

	repo, err := gitrepo.OpenPath(dir)
	if err != nil {
		t.Fatalf("OpenPath() error = %v", err)
	}
	t.Cleanup(func() { _ = repo.Close() })
	return dir, repo
}

func runGit(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, output)
	}
}

package agentcheck

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/gitops"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// Reader is the Entire checkpoint read surface AgentCheck needs.
type Reader interface {
	checkpoint.CheckpointReader
	checkpoint.SessionReader
}

// GraphProvider contributes optional graph evidence.
type GraphProvider interface {
	CollectGraphEvidence(ctx context.Context, req GraphRequest) (GraphContext, error)
}

// GraphRequest describes the changed files AgentCheck wants structural context for.
type GraphRequest struct {
	CheckpointID id.CheckpointID
	ChangedFiles []FileChange
	FilesTouched []string
}

// Builder creates AgentCheck contexts from Entire checkpoint APIs.
type Builder struct {
	Reader Reader
	Repo   *git.Repository
	RepoRoot string
	Graph GraphProvider
}

// Build reads one checkpoint and adapts it into AgentCheck's context contract.
func (b Builder) Build(ctx context.Context, checkpointID id.CheckpointID) (*Context, error) {
	if checkpointID.IsEmpty() {
		return nil, errors.New("agentcheck context: checkpoint ID is required")
	}
	if b.Reader == nil {
		return nil, errors.New("agentcheck context: checkpoint reader is required")
	}

	summary, err := checkpoint.ReadCheckpoint(ctx, b.Reader, checkpointID)
	if err != nil {
		return nil, fmt.Errorf("agentcheck context: read checkpoint %s: %w", checkpointID, err)
	}

	ac := &Context{
		CheckpointID: checkpointID,
		Checkpoint: Checkpoint{
			ID:               summary.CheckpointID,
			Strategy:         summary.Strategy,
			Branch:           summary.Branch,
			CommitSHA:        summary.CommitSHA,
			CheckpointsCount: summary.CheckpointsCount,
			SessionCount:     len(summary.Sessions),
			Imported:         summary.Imported,
			HasReview:        summary.HasReview,
			HasInvestigation: summary.HasInvestigation,
		},
		FilesTouched: appendSortedUnique(nil, summary.FilesTouched...),
		TokenUsage: summary.TokenUsage,
		Graph: GraphContext{Available: false, UnavailableReason: "graph provider not configured"},
		Provenance: Provenance{
			CheckpointID: checkpointID,
			Sources: []EvidenceSource{
				{Kind: "checkpoint", ID: checkpointID.String(), Description: "Entire checkpoint metadata", Available: true},
			},
		},
	}

	if err := b.addSessions(ctx, ac, checkpointID, summary); err != nil {
		return nil, err
	}

	gitEvidence := b.collectGitEvidence(ctx, checkpointID, summary)
	ac.Git = gitEvidence
	ac.ChangedFiles = changedFilesFromGit(gitEvidence)
	ac.Provenance.CommitSHAs = commitSHAs(gitEvidence.AssociatedCommits)
	ac.Provenance.Sources = append(ac.Provenance.Sources,
		EvidenceSource{Kind: "git", ID: strings.Join(ac.Provenance.CommitSHAs, ","), Description: "Commits and diff associated through Entire-Checkpoint trailers or checkpoint commit metadata", Available: len(gitEvidence.AssociatedCommits) > 0},
	)

	graph := GraphContext{Available: false, UnavailableReason: "graph provider not configured"}
	if b.Graph != nil {
		graph, err = b.Graph.CollectGraphEvidence(ctx, GraphRequest{
			CheckpointID: checkpointID,
			ChangedFiles: ac.ChangedFiles,
			FilesTouched: ac.FilesTouched,
		})
		if err != nil {
			graph = GraphContext{Available: false, UnavailableReason: err.Error()}
		} else if !graph.Available && graph.UnavailableReason == "" {
			graph.UnavailableReason = "graph provider returned no evidence"
		}
	}
	ac.Graph = graph
	ac.Provenance.Sources = append(ac.Provenance.Sources,
		EvidenceSource{Kind: "graph", Description: "Optional Entire Graph structural evidence", Available: graph.Available},
	)

	return ac, nil
}

func (b Builder) addSessions(ctx context.Context, ac *Context, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
	for i := range summary.Sessions {
		content, err := b.Reader.ReadSessionContent(ctx, checkpointID, i)
		if err != nil {
			return fmt.Errorf("agentcheck context: read checkpoint %s session %d: %w", checkpointID, i, err)
		}
		if content == nil {
			return fmt.Errorf("agentcheck context: checkpoint %s session %d returned no content", checkpointID, i)
		}
		meta := content.Metadata
		prompts := checkpoint.SplitPromptContent(content.Prompts)
		session := Session{
			Index:                     i,
			SessionID:                 meta.SessionID,
			CreatedAt:                 meta.CreatedAt,
			Strategy:                  meta.Strategy,
			Branch:                    meta.Branch,
			CommitSHA:                 meta.CommitSHA,
			CheckpointsCount:          meta.CheckpointsCount,
			SaveStepCount:             meta.SaveStepCount,
			FilesTouched:              appendSortedUnique(nil, meta.FilesTouched...),
			AgentType:                 string(meta.Agent),
			Model:                     meta.Model,
			TurnID:                    meta.TurnID,
			Kind:                      meta.Kind,
			TokenUsage:                meta.TokenUsage,
			TranscriptStart:           meta.GetTranscriptStart(),
			CompactTranscriptStart:    meta.CompactTranscriptStart,
			PromptCount:               len(prompts),
			SkillEventCount:           len(meta.SkillEvents),
		}
		if len(content.Transcript) == 0 {
			session.TranscriptUnavailable = true
			session.TranscriptUnavailableReason = "session transcript empty or unavailable"
		}
		for j, prompt := range prompts {
			p := Prompt{SessionIndex: i, PromptIndex: j, Text: prompt}
			session.Prompts = append(session.Prompts, p)
			ac.ScopedPrompts = append(ac.ScopedPrompts, p)
			if ac.DeveloperPrompt == "" {
				ac.DeveloperPrompt = prompt
			}
		}
		if ac.AgentType == "" {
			ac.AgentType = session.AgentType
		}
		if ac.Model == "" {
			ac.Model = session.Model
		}
		ac.Sessions = append(ac.Sessions, session)
		if session.SessionID != "" {
			ac.Provenance.SessionIDs = append(ac.Provenance.SessionIDs, session.SessionID)
		}
		if len(content.Transcript) > 0 && !ac.Transcript.Available {
			ac.Transcript = TranscriptRef{Available: true, SessionID: session.SessionID, SessionIndex: i, ByteLength: len(content.Transcript)}
		}
	}
	if !ac.Transcript.Available {
		ac.Transcript = TranscriptRef{Available: false, UnavailableReason: "no session transcript bytes available"}
	}
	ac.Provenance.SessionIDs = appendSortedUnique(nil, ac.Provenance.SessionIDs...)
	ac.Provenance.Sources = append(ac.Provenance.Sources,
		EvidenceSource{Kind: "session", ID: strings.Join(ac.Provenance.SessionIDs, ","), Description: "Entire checkpoint session metadata, prompts, and transcript availability", Available: len(ac.Sessions) > 0},
	)
	return nil
}

func (b Builder) collectGitEvidence(ctx context.Context, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) GitEvidence {
	if b.Repo == nil {
		return GitEvidence{DiffUnavailableReason: "git repository not configured", ChangedFilesUnavailable: "git repository not configured"}
	}
	commits, err := findAssociatedCommits(ctx, b.Repo, checkpointID, summary.CommitSHA)
	if err != nil {
		return GitEvidence{DiffUnavailableReason: err.Error(), ChangedFilesUnavailable: err.Error()}
	}
	if len(commits) == 0 {
		return GitEvidence{DiffUnavailableReason: "no associated commits found", ChangedFilesUnavailable: "no associated commits found"}
	}

	evidence := GitEvidence{AssociatedCommits: commits}
	if b.RepoRoot == "" {
		evidence.DiffUnavailableReason = "repository root not configured"
		evidence.ChangedFilesUnavailable = "repository root not configured"
		return evidence
	}
	var diff strings.Builder
	changed := map[string]struct{}{}
	for _, commit := range commits {
		parent := firstParentHash(ctx, b.Repo, commit.SHA)
		files, filesErr := gitops.DiffTreeFileList(ctx, b.RepoRoot, parent, commit.SHA)
		if filesErr != nil && evidence.ChangedFilesUnavailable == "" {
			evidence.ChangedFilesUnavailable = filesErr.Error()
		}
		for _, file := range files {
			changed[file] = struct{}{}
		}
		patch, patchErr := gitShowPatch(ctx, b.RepoRoot, commit.SHA)
		if patchErr != nil {
			if evidence.DiffUnavailableReason == "" {
				evidence.DiffUnavailableReason = patchErr.Error()
			}
			continue
		}
		if diff.Len() > 0 {
			diff.WriteString("\n")
		}
		diff.WriteString(patch)
	}
	evidence.ChangedFilesUnavailable = emptyIfChanged(evidence.ChangedFilesUnavailable, changed)
	evidence.Diff = diff.String()
	if evidence.Diff != "" {
		evidence.DiffUnavailableReason = ""
	}
	return evidence
}

func findAssociatedCommits(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, anchorSHA string) ([]AssociatedCommit, error) {
	seen := map[string]bool{}
	var result []AssociatedCommit
	if anchorSHA != "" {
		commit, err := repo.CommitObject(plumbing.NewHash(anchorSHA))
		if err == nil {
			result = append(result, associatedCommit(commit, "checkpoint_metadata"))
			seen[commit.Hash.String()] = true
		}
	}

	head, err := repo.Head()
	if err != nil {
		if len(result) > 0 {
			return result, nil
		}
		return nil, fmt.Errorf("resolve HEAD: %w", err)
	}
	iter, err := repo.Log(&git.LogOptions{From: head.Hash(), Order: git.LogOrderCommitterTime})
	if err != nil {
		if len(result) > 0 {
			return result, nil
		}
		return nil, fmt.Errorf("read git log: %w", err)
	}
	defer iter.Close()
	err = iter.ForEach(func(commit *object.Commit) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		for _, cpID := range trailers.ParseAllCheckpoints(commit.Message) {
			if cpID == checkpointID && !seen[commit.Hash.String()] {
				result = append(result, associatedCommit(commit, "commit_trailer"))
				seen[commit.Hash.String()] = true
				break
			}
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return result, nil
}

func associatedCommit(commit *object.Commit, source string) AssociatedCommit {
	subject, _, _ := strings.Cut(commit.Message, "\n")
	return AssociatedCommit{
		SHA:     commit.Hash.String(),
		Subject: strings.TrimSpace(subject),
		Author:  commit.Author.Name,
		Date:    commit.Author.When,
		Source:  source,
	}
}

func firstParentHash(ctx context.Context, repo *git.Repository, sha string) string {
	commit, err := repo.CommitObject(plumbing.NewHash(sha))
	if err != nil || commit.NumParents() == 0 {
		return ""
	}
	parent, err := commit.Parent(0)
	if err != nil {
		return ""
	}
	if err := ctx.Err(); err != nil {
		return ""
	}
	return parent.Hash.String()
}

func gitShowPatch(ctx context.Context, repoRoot, sha string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "show", "--format=commit %H%n%B", "--no-ext-diff", "--find-renames", sha)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("git show %s: %w: %s", sha, err, strings.TrimSpace(stderr.String()))
	}
	return stdout.String(), nil
}

func changedFilesFromGit(gitEvidence GitEvidence) []FileChange {
	paths := map[string]struct{}{}
	for _, commit := range gitEvidence.AssociatedCommits {
		_ = commit
	}
	for _, line := range strings.Split(gitEvidence.Diff, "\n") {
		if strings.HasPrefix(line, "diff --git ") {
			parts := strings.Fields(line)
			if len(parts) >= 4 {
				path := strings.TrimPrefix(parts[3], "b/")
				paths[path] = struct{}{}
			}
		}
	}
	out := make([]FileChange, 0, len(paths))
	for path := range paths {
		out = append(out, FileChange{Path: path})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	return out
}

func commitSHAs(commits []AssociatedCommit) []string {
	out := make([]string, 0, len(commits))
	for _, commit := range commits {
		out = append(out, commit.SHA)
	}
	return out
}

func appendSortedUnique(dst []string, values ...string) []string {
	seen := map[string]struct{}{}
	for _, existing := range dst {
		seen[existing] = struct{}{}
	}
	for _, value := range values {
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		dst = append(dst, value)
	}
	sort.Strings(dst)
	return dst
}

func emptyIfChanged(reason string, changed map[string]struct{}) string {
	if len(changed) > 0 {
		return ""
	}
	return reason
}

// Package agentcheck contains the AgentCheck context boundary.
package agentcheck

import (
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// Context is the stable input that future AgentCheck evaluators consume.
// It intentionally contains AgentCheck-owned evidence shapes instead of
// checkpoint storage structs.
type Context struct {
	CheckpointID id.CheckpointID `json:"checkpoint_id"`
	Checkpoint   Checkpoint      `json:"checkpoint"`
	Sessions     []Session       `json:"sessions"`

	DeveloperPrompt string   `json:"developer_prompt,omitempty"`
	ScopedPrompts   []Prompt `json:"scoped_prompts,omitempty"`

	AgentType  string            `json:"agent_type,omitempty"`
	Model      string            `json:"model,omitempty"`
	TokenUsage *types.TokenUsage `json:"token_usage,omitempty"`

	FilesTouched []string    `json:"files_touched,omitempty"`
	ChangedFiles []FileChange `json:"changed_files,omitempty"`

	Git        GitEvidence   `json:"git"`
	Transcript TranscriptRef `json:"transcript,omitempty"`
	TaskRecords []TaskRecord `json:"task_records,omitempty"`
	Graph      GraphContext  `json:"graph"`

	Provenance Provenance `json:"provenance"`
}

// Checkpoint captures checkpoint-level facts needed by AgentCheck.
type Checkpoint struct {
	ID               id.CheckpointID `json:"id"`
	Strategy         string          `json:"strategy,omitempty"`
	Branch           string          `json:"branch,omitempty"`
	CommitSHA        string          `json:"commit_sha,omitempty"`
	CheckpointsCount int             `json:"checkpoints_count,omitempty"`
	SessionCount     int             `json:"session_count"`
	Imported         bool            `json:"imported,omitempty"`
	HasReview        bool            `json:"has_review,omitempty"`
	HasInvestigation bool            `json:"has_investigation,omitempty"`
}

// Session captures one Entire session's context inside a checkpoint.
type Session struct {
	Index                     int               `json:"index"`
	SessionID                 string            `json:"session_id,omitempty"`
	CreatedAt                 time.Time         `json:"created_at,omitempty"`
	Strategy                  string            `json:"strategy,omitempty"`
	Branch                    string            `json:"branch,omitempty"`
	CommitSHA                 string            `json:"commit_sha,omitempty"`
	CheckpointsCount          int               `json:"checkpoints_count,omitempty"`
	SaveStepCount             int               `json:"save_step_count,omitempty"`
	FilesTouched              []string          `json:"files_touched,omitempty"`
	AgentType                 string            `json:"agent_type,omitempty"`
	Model                     string            `json:"model,omitempty"`
	TurnID                    string            `json:"turn_id,omitempty"`
	Kind                      string            `json:"kind,omitempty"`
	TokenUsage                *types.TokenUsage `json:"token_usage,omitempty"`
	TranscriptStart           int               `json:"transcript_start,omitempty"`
	CompactTranscriptStart    *int              `json:"compact_transcript_start,omitempty"`
	TranscriptUnavailable     bool              `json:"transcript_unavailable,omitempty"`
	TranscriptUnavailableReason string           `json:"transcript_unavailable_reason,omitempty"`
	PromptCount               int               `json:"prompt_count,omitempty"`
	Prompts                   []Prompt          `json:"prompts,omitempty"`
	SkillEventCount           int               `json:"skill_event_count,omitempty"`
}

// Prompt preserves raw prompt text as stored in Entire checkpoint prompt data.
type Prompt struct {
	SessionIndex int    `json:"session_index"`
	PromptIndex  int    `json:"prompt_index"`
	Text         string `json:"text"`
}

// FileChange is a changed path associated with checkpoint commits.
type FileChange struct {
	Path   string `json:"path"`
	Status string `json:"status,omitempty"`
}

// AssociatedCommit describes a git commit linked to a checkpoint.
type AssociatedCommit struct {
	SHA     string    `json:"sha"`
	Subject string    `json:"subject,omitempty"`
	Author  string    `json:"author,omitempty"`
	Date    time.Time `json:"date,omitempty"`
	Source  string    `json:"source"`
}

// GitEvidence is the checkpoint-associated git evidence AgentCheck saw.
type GitEvidence struct {
	AssociatedCommits       []AssociatedCommit `json:"associated_commits,omitempty"`
	Diff                    string             `json:"diff,omitempty"`
	DiffUnavailableReason   string             `json:"diff_unavailable_reason,omitempty"`
	ChangedFilesUnavailable string             `json:"changed_files_unavailable_reason,omitempty"`
}

// TranscriptRef records whether transcript bytes were available without making
// downstream evaluators understand checkpoint storage paths.
type TranscriptRef struct {
	Available          bool   `json:"available"`
	SessionID          string `json:"session_id,omitempty"`
	SessionIndex       int    `json:"session_index,omitempty"`
	ByteLength         int    `json:"byte_length,omitempty"`
	UnavailableReason string `json:"unavailable_reason,omitempty"`
}

// TaskRecord is reserved for durable subagent/task records when a stable reader
// surface is available. It remains empty rather than fabricated.
type TaskRecord struct {
	ToolUseID string `json:"tool_use_id,omitempty"`
	AgentID   string `json:"agent_id,omitempty"`
}

// GraphContext records optional graph evidence. Unavailable Graph never blocks
// context construction.
type GraphContext struct {
	Available          bool            `json:"available"`
	UnavailableReason  string          `json:"unavailable_reason,omitempty"`
	Evidence           []GraphEvidence `json:"evidence,omitempty"`
}

// GraphEvidence is an adapter-owned shape for structural evidence supplied by
// Entire Graph or a test double.
type GraphEvidence struct {
	Query  string   `json:"query,omitempty"`
	Symbol string   `json:"symbol,omitempty"`
	Kind   string   `json:"kind,omitempty"`
	Paths  []string `json:"paths,omitempty"`
	Detail string   `json:"detail,omitempty"`
}

// Provenance carries the identifiers needed to trace future findings back to
// checkpoint, session, git, transcript, and graph evidence.
type Provenance struct {
	CheckpointID id.CheckpointID `json:"checkpoint_id"`
	SessionIDs   []string        `json:"session_ids,omitempty"`
	CommitSHAs   []string        `json:"commit_shas,omitempty"`
	Sources      []EvidenceSource `json:"sources,omitempty"`
}

// EvidenceSource identifies where one class of context evidence came from.
type EvidenceSource struct {
	Kind        string `json:"kind"`
	ID          string `json:"id,omitempty"`
	Description string `json:"description,omitempty"`
	Available   bool   `json:"available"`
}

