186: func (b Builder) collectGitEvidence(ctx context.Context, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) GitEvidence {
187: 	if b.Repo == nil {
188: 		return GitEvidence{DiffUnavailableReason: "git repository not configured", ChangedFilesUnavailable: "git repository not configured"}
189: 	}
190: 	commits, err := findAssociatedCommits(ctx, b.Repo, checkpointID, summary.CommitSHA)
191: 	if err != nil {
192: 		return GitEvidence{DiffUnavailableReason: err.Error(), ChangedFilesUnavailable: err.Error()}
193: 	}
194: 	if len(commits) == 0 {
195: 		return GitEvidence{DiffUnavailableReason: "no associated commits found", ChangedFilesUnavailable: "no associated commits found"}
196: 	}
197: 
198: 	evidence := GitEvidence{AssociatedCommits: commits}
199: 	if b.RepoRoot == "" {
200: 		evidence.DiffUnavailableReason = "repository root not configured"
201: 		evidence.ChangedFilesUnavailable = "repository root not configured"
202: 		return evidence
203: 	}
204: 	var diff strings.Builder
205: 	changed := map[string]struct{}{}
206: 	for _, commit := range commits {
207: 		parent := firstParentHash(ctx, b.Repo, commit.SHA)
208: 		files, filesErr := gitops.DiffTreeFileList(ctx, b.RepoRoot, parent, commit.SHA)
209: 		if filesErr != nil && evidence.ChangedFilesUnavailable == "" {
210: 			evidence.ChangedFilesUnavailable = filesErr.Error()
211: 		}
212: 		for _, file := range files {
213: 			changed[file] = struct{}{}
214: 		}
215: 		patch, patchErr := gitShowPatch(ctx, b.RepoRoot, commit.SHA)
216: 		if patchErr != nil {
217: 			if evidence.DiffUnavailableReason == "" {
218: 				evidence.DiffUnavailableReason = patchErr.Error()
219: 			}
220: 			continue
221: 		}
222: 		if diff.Len() > 0 {
223: 			diff.WriteString("\n")
224: 		}
225: 		diff.WriteString(patch)
226: 	}
227: 	evidence.ChangedFiles = fileChangesFromSet(changed)
228: 	evidence.ChangedFilesUnavailable = emptyIfChanged(evidence.ChangedFilesUnavailable, changed)
229: 	evidence.Diff = diff.String()
230: 	if evidence.Diff != "" {
231: 		evidence.DiffUnavailableReason = ""
232: 	}
233: 	return evidence
234: }
235: 
236: func findAssociatedCommits(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, anchorSHA string) ([]AssociatedCommit, error) {
237: 	seen := map[string]bool{}
238: 	var result []AssociatedCommit
239: 	if anchorSHA != "" {
240: 		commit, err := repo.CommitObject(plumbing.NewHash(anchorSHA))
241: 		if err == nil {
242: 			result = append(result, associatedCommit(commit, "checkpoint_metadata"))
243: 			seen[commit.Hash.String()] = true
244: 		}
245: 	}
246: 
247: 	head, err := repo.Head()
248: 	if err != nil {
249: 		if len(result) > 0 {
250: 			return result, nil
251: 		}
252: 		return nil, fmt.Errorf("resolve HEAD: %w", err)
253: 	}
254: 	iter, err := repo.Log(&git.LogOptions{From: head.Hash(), Order: git.LogOrderCommitterTime})
255: 	if err != nil {
256: 		if len(result) > 0 {
257: 			return result, nil
258: 		}
259: 		return nil, fmt.Errorf("read git log: %w", err)
260: 	}
261: 	defer iter.Close()
262: 	err = iter.ForEach(func(commit *object.Commit) error {
263: 		if err := ctx.Err(); err != nil {
264: 			return err
265: 		}
266: 		for _, cpID := range trailers.ParseAllCheckpoints(commit.Message) {
267: 			if cpID == checkpointID && !seen[commit.Hash.String()] {
268: 				result = append(result, associatedCommit(commit, "commit_trailer"))
269: 				seen[commit.Hash.String()] = true
270: 				break
271: 			}
272: 		}
273: 		return nil
274: 	})
275: 	if err != nil {
276: 		return nil, err
277: 	}
278: 	return result, nil
279: }
280: 
281: func associatedCommit(commit *object.Commit, source string) AssociatedCommit {
282: 	subject, _, _ := strings.Cut(commit.Message, "\n")
283: 	return AssociatedCommit{
284: 		SHA:     commit.Hash.String(),
285: 		Subject: strings.TrimSpace(subject),
286: 		Author:  commit.Author.Name,
287: 		Date:    commit.Author.When,
288: 		Source:  source,
289: 	}
290: }
291: 
292: func firstParentHash(ctx context.Context, repo *git.Repository, sha string) string {
293: 	commit, err := repo.CommitObject(plumbing.NewHash(sha))
294: 	if err != nil || commit.NumParents() == 0 {
295: 		return ""
296: 	}
297: 	parent, err := commit.Parent(0)
298: 	if err != nil {
299: 		return ""
300: 	}
301: 	if err := ctx.Err(); err != nil {
302: 		return ""
303: 	}
304: 	return parent.Hash.String()
305: }
306: 
307: func gitShowPatch(ctx context.Context, repoRoot, sha string) (string, error) {
308: 	cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "show", "--format=commit %H%n%B", "--no-ext-diff", "--find-renames", sha)
309: 	var stdout, stderr bytes.Buffer
310: 	cmd.Stdout = &stdout
311: 	cmd.Stderr = &stderr
312: 	if err := cmd.Run(); err != nil {
313: 		return "", fmt.Errorf("git show %s: %w: %s", sha, err, strings.TrimSpace(stderr.String()))
314: 	}
315: 	return stdout.String(), nil
316: }
317: 
318: func fileChangesFromSet(paths map[string]struct{}) []FileChange {
319: 	out := make([]FileChange, 0, len(paths))
320: 	for path := range paths {
321: 		out = append(out, FileChange{Path: path})
322: 	}
323: 	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
324: 	return out
325: }
326: 
327: func commitSHAs(commits []AssociatedCommit) []string {
328: 	out := make([]string, 0, len(commits))
329: 	for _, commit := range commits {
330: 		out = append(out, commit.SHA)
331: 	}
332: 	return out
333: }
334: 
335: func appendSortedUnique(dst []string, values ...string) []string {
336: 	seen := map[string]struct{}{}
337: 	for _, existing := range dst {
338: 		seen[existing] = struct{}{}
339: 	}
340: 	for _, value := range values {
341: 		if value == "" {
342: 			continue
343: 		}
344: 		if _, ok := seen[value]; ok {
345: 			continue
346: 		}
347: 		seen[value] = struct{}{}
348: 		dst = append(dst, value)
349: 	}
350: 	sort.Strings(dst)
351: 	return dst
352: }
353: 
354: func emptyIfChanged(reason string, changed map[string]struct{}) string {
355: 	if len(changed) > 0 {
356: 		return ""
357: 	}
358: 	return reason
359: }

