236: func findAssociatedCommits(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, anchorSHA string) ([]AssociatedCommit, error) {
237: 	seen := map[string]bool{}
238: 	var result []AssociatedCommit
239: 	if anchorSHA != "" {
240: 		commit, err := repo.CommitObject(plumbing.NewHash(anchorSHA))
241: 		if err == nil {
242: 			result = append(result, associatedCommit(commit, "checkpoint_metadata"))
243: 			seen[commit.Hash.String()] = true
244: 		}
245: 	}
246: 
247: 	head, err := repo.Head()
248: 	if err != nil {
249: 		if len(result) > 0 {
250: 			return result, nil
251: 		}
252: 		return nil, fmt.Errorf("resolve HEAD: %w", err)
253: 	}
254: 	iter, err := repo.Log(&git.LogOptions{From: head.Hash(), Order: git.LogOrderCommitterTime})
255: 	if err != nil {
256: 		if len(result) > 0 {
257: 			return result, nil
258: 		}
259: 		return nil, fmt.Errorf("read git log: %w", err)
260: 	}
261: 	defer iter.Close()
262: 	err = iter.ForEach(func(commit *object.Commit) error {
263: 		if err := ctx.Err(); err != nil {
264: 			return err
265: 		}
266: 		for _, cpID := range trailers.ParseAllCheckpoints(commit.Message) {
267: 			if cpID == checkpointID && !seen[commit.Hash.String()] {
268: 				result = append(result, associatedCommit(commit, "commit_trailer"))
269: 				seen[commit.Hash.String()] = true
270: 				break
271: 			}
272: 		}
273: 		return nil
274: 	})
275: 	if err != nil {
276: 		return nil, err
277: 	}
278: 	return result, nil
279: }
