 35: 	CheckpointID id.CheckpointID
 36: 	ChangedFiles []FileChange
 37: 	FilesTouched []string
 38: }
 39: 
 40: // Builder creates AgentCheck contexts from Entire checkpoint APIs.
 41: type Builder struct {
 42: 	Reader Reader
 43: 	Repo   *git.Repository
 44: 	RepoRoot string
 45: 	Graph GraphProvider
 46: }
 47: 
 48: // Build reads one checkpoint and adapts it into AgentCheck's context contract.
 49: func (b Builder) Build(ctx context.Context, checkpointID id.CheckpointID) (*Context, error) {
 50: 	if checkpointID.IsEmpty() {
 51: 		return nil, errors.New("agentcheck context: checkpoint ID is required")
 52: 	}
 53: 	if b.Reader == nil {
 54: 		return nil, errors.New("agentcheck context: checkpoint reader is required")
 55: 	}
 56: 
 57: 	summary, err := checkpoint.ReadCheckpoint(ctx, b.Reader, checkpointID)
 58: 	if err != nil {
 59: 		return nil, fmt.Errorf("agentcheck context: read checkpoint %s: %w", checkpointID, err)
 60: 	}
 61: 
 62: 	ac := &Context{
 63: 		CheckpointID: checkpointID,
 64: 		Checkpoint: Checkpoint{
 65: 			ID:               summary.CheckpointID,
 66: 			Strategy:         summary.Strategy,
 67: 			Branch:           summary.Branch,
 68: 			CommitSHA:        summary.CommitSHA,
 69: 			CheckpointsCount: summary.CheckpointsCount,
 70: 			SessionCount:     len(summary.Sessions),
 71: 			Imported:         summary.Imported,
 72: 			HasReview:        summary.HasReview,
 73: 			HasInvestigation: summary.HasInvestigation,
 74: 		},
 75: 		FilesTouched: appendSortedUnique(nil, summary.FilesTouched...),
 76: 		TokenUsage: summary.TokenUsage,
 77: 		Graph: GraphContext{Available: false, UnavailableReason: "graph provider not configured"},
 78: 		Provenance: Provenance{
 79: 			CheckpointID: checkpointID,
 80: 			Sources: []EvidenceSource{
 81: 				{Kind: "checkpoint", ID: checkpointID.String(), Description: "Entire checkpoint metadata", Available: true},
 82: 			},
 83: 		},
 84: 	}
 85: 
 86: 	if err := b.addSessions(ctx, ac, checkpointID, summary); err != nil {
 87: 		return nil, err
 88: 	}
 89: 
 90: 	gitEvidence := b.collectGitEvidence(ctx, checkpointID, summary)
 91: 	ac.Git = gitEvidence
 92: 	ac.ChangedFiles = gitEvidence.ChangedFiles
 93: 	ac.Provenance.CommitSHAs = commitSHAs(gitEvidence.AssociatedCommits)
 94: 	ac.Provenance.Sources = append(ac.Provenance.Sources,
 95: 		EvidenceSource{Kind: "git", ID: strings.Join(ac.Provenance.CommitSHAs, ","), Description: "Commits and diff associated through Entire-Checkpoint trailers or checkpoint commit metadata", Available: len(gitEvidence.AssociatedCommits) > 0},
 96: 	)
 97: 
 98: 	graph := GraphContext{Available: false, UnavailableReason: "graph provider not configured"}
 99: 	if b.Graph != nil {
100: 		graph, err = b.Graph.CollectGraphEvidence(ctx, GraphRequest{
101: 			CheckpointID: checkpointID,
102: 			ChangedFiles: ac.ChangedFiles,
103: 			FilesTouched: ac.FilesTouched,
104: 		})
105: 		if err != nil {
106: 			graph = GraphContext{Available: false, UnavailableReason: err.Error()}
107: 		} else if !graph.Available && graph.UnavailableReason == "" {
108: 			graph.UnavailableReason = "graph provider returned no evidence"
109: 		}
110: 	}
111: 	ac.Graph = graph
112: 	ac.Provenance.Sources = append(ac.Provenance.Sources,
113: 		EvidenceSource{Kind: "graph", Description: "Optional Entire Graph structural evidence", Available: graph.Available},
114: 	)
115: 
116: 	return ac, nil
117: }
