119: func (b Builder) addSessions(ctx context.Context, ac *Context, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
120: 	for i := range summary.Sessions {
121: 		content, err := b.Reader.ReadSessionContent(ctx, checkpointID, i)
122: 		if err != nil {
123: 			return fmt.Errorf("agentcheck context: read checkpoint %s session %d: %w", checkpointID, i, err)
124: 		}
125: 		if content == nil {
126: 			return fmt.Errorf("agentcheck context: checkpoint %s session %d returned no content", checkpointID, i)
127: 		}
128: 		meta := content.Metadata
129: 		prompts := checkpoint.SplitPromptContent(content.Prompts)
130: 		session := Session{
131: 			Index:                     i,
132: 			SessionID:                 meta.SessionID,
133: 			CreatedAt:                 meta.CreatedAt,
134: 			Strategy:                  meta.Strategy,
135: 			Branch:                    meta.Branch,
136: 			CommitSHA:                 meta.CommitSHA,
137: 			CheckpointsCount:          meta.CheckpointsCount,
138: 			SaveStepCount:             meta.SaveStepCount,
139: 			FilesTouched:              appendSortedUnique(nil, meta.FilesTouched...),
140: 			AgentType:                 string(meta.Agent),
141: 			Model:                     meta.Model,
142: 			TurnID:                    meta.TurnID,
143: 			Kind:                      meta.Kind,
144: 			TokenUsage:                meta.TokenUsage,
145: 			TranscriptStart:           meta.GetTranscriptStart(),
146: 			CompactTranscriptStart:    meta.CompactTranscriptStart,
147: 			PromptCount:               len(prompts),
148: 			SkillEventCount:           len(meta.SkillEvents),
149: 		}
150: 		if len(content.Transcript) == 0 {
151: 			session.TranscriptUnavailable = true
152: 			session.TranscriptUnavailableReason = "session transcript empty or unavailable"
153: 		}
154: 		for j, prompt := range prompts {
155: 			p := Prompt{SessionIndex: i, PromptIndex: j, Text: prompt}
156: 			session.Prompts = append(session.Prompts, p)
157: 			ac.ScopedPrompts = append(ac.ScopedPrompts, p)
158: 			if ac.DeveloperPrompt == "" {
159: 				ac.DeveloperPrompt = prompt
160: 			}
161: 		}
162: 		if ac.AgentType == "" {
163: 			ac.AgentType = session.AgentType
164: 		}
165: 		if ac.Model == "" {
166: 			ac.Model = session.Model
167: 		}
168: 		ac.Sessions = append(ac.Sessions, session)
169: 		if session.SessionID != "" {
170: 			ac.Provenance.SessionIDs = append(ac.Provenance.SessionIDs, session.SessionID)
171: 		}
172: 		if len(content.Transcript) > 0 && !ac.Transcript.Available {
173: 			ac.Transcript = TranscriptRef{Available: true, SessionID: session.SessionID, SessionIndex: i, ByteLength: len(content.Transcript)}
174: 		}
175: 	}
176: 	if !ac.Transcript.Available {
177: 		ac.Transcript = TranscriptRef{Available: false, UnavailableReason: "no session transcript bytes available"}
178: 	}
179: 	ac.Provenance.SessionIDs = appendSortedUnique(nil, ac.Provenance.SessionIDs...)
180: 	ac.Provenance.Sources = append(ac.Provenance.Sources,
181: 		EvidenceSource{Kind: "session", ID: strings.Join(ac.Provenance.SessionIDs, ","), Description: "Entire checkpoint session metadata, prompts, and transcript availability", Available: len(ac.Sessions) > 0},
182: 	)
183: 	return nil
184: }
