  44: 	RepoRoot string
  45: 	Graph GraphProvider
  46: }
  47: 
  48: // Build reads one checkpoint and adapts it into AgentCheck's context contract.
  49: func (b Builder) Build(ctx context.Context, checkpointID id.CheckpointID) (*Context, error) {
  50: 	if checkpointID.IsEmpty() {
  51: 		return nil, errors.New("agentcheck context: checkpoint ID is required")
  52: 	}
  53: 	if b.Reader == nil {
  54: 		return nil, errors.New("agentcheck context: checkpoint reader is required")
  55: 	}
  56: 
  57: 	summary, err := checkpoint.ReadCheckpoint(ctx, b.Reader, checkpointID)
  58: 	if err != nil {
  59: 		return nil, fmt.Errorf("agentcheck context: read checkpoint %s: %w", checkpointID, err)
  60: 	}
  61: 
  62: 	ac := &Context{
  63: 		CheckpointID: checkpointID,
  64: 		Checkpoint: Checkpoint{
  65: 			ID:               summary.CheckpointID,
  66: 			Strategy:         summary.Strategy,
  67: 			Branch:           summary.Branch,
  68: 			CommitSHA:        summary.CommitSHA,
  69: 			CheckpointsCount: summary.CheckpointsCount,
  70: 			SessionCount:     len(summary.Sessions),
  71: 			Imported:         summary.Imported,
  72: 			HasReview:        summary.HasReview,
  73: 			HasInvestigation: summary.HasInvestigation,
  74: 		},
  75: 		FilesTouched: appendSortedUnique(nil, summary.FilesTouched...),
  76: 		TokenUsage: summary.TokenUsage,
  77: 		Graph: GraphContext{Available: false, UnavailableReason: "graph provider not configured"},
  78: 		Provenance: Provenance{
  79: 			CheckpointID: checkpointID,
  80: 			Sources: []EvidenceSource{
  81: 				{Kind: "checkpoint", ID: checkpointID.String(), Description: "Entire checkpoint metadata", Available: true},
  82: 			},
  83: 		},
  84: 	}
  85: 
  86: 	if err := b.addSessions(ctx, ac, checkpointID, summary); err != nil {
  87: 		return nil, err
  88: 	}
  89: 
  90: 	gitEvidence := b.collectGitEvidence(ctx, checkpointID, summary)
  91: 	ac.Git = gitEvidence
  92: 	ac.ChangedFiles = gitEvidence.ChangedFiles
  93: 	ac.Provenance.CommitSHAs = commitSHAs(gitEvidence.AssociatedCommits)
  94: 	ac.Provenance.Sources = append(ac.Provenance.Sources,
  95: 		EvidenceSource{Kind: "git", ID: strings.Join(ac.Provenance.CommitSHAs, ","), Description: "Commits and diff associated through Entire-Checkpoint trailers or checkpoint commit metadata", Available: len(gitEvidence.AssociatedCommits) > 0},
  96: 	)
  97: 
  98: 	graph := GraphContext{Available: false, UnavailableReason: "graph provider not configured"}
  99: 	if b.Graph != nil {
 100: 		graph, err = b.Graph.CollectGraphEvidence(ctx, GraphRequest{
 101: 			CheckpointID: checkpointID,
 102: 			ChangedFiles: ac.ChangedFiles,
 103: 			FilesTouched: ac.FilesTouched,
 104: 		})
 105: 		if err != nil {
 106: 			graph = GraphContext{Available: false, UnavailableReason: err.Error()}
 107: 		} else if !graph.Available && graph.UnavailableReason == "" {
 108: 			graph.UnavailableReason = "graph provider returned no evidence"
 109: 		}
 110: 	}
 111: 	ac.Graph = graph
 112: 	ac.Provenance.Sources = append(ac.Provenance.Sources,
 113: 		EvidenceSource{Kind: "graph", Description: "Optional Entire Graph structural evidence", Available: graph.Available},
 114: 	)
 115: 
 116: 	return ac, nil
 117: }
 118: 
 119: func (b Builder) addSessions(ctx context.Context, ac *Context, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
 120: 	for i := range summary.Sessions {
 121: 		content, err := b.Reader.ReadSessionContent(ctx, checkpointID, i)
 122: 		if err != nil {
 123: 			return fmt.Errorf("agentcheck context: read checkpoint %s session %d: %w", checkpointID, i, err)
 124: 		}
 125: 		if content == nil {
 126: 			return fmt.Errorf("agentcheck context: checkpoint %s session %d returned no content", checkpointID, i)
 127: 		}
 128: 		meta := content.Metadata
 129: 		prompts := checkpoint.SplitPromptContent(content.Prompts)
 130: 		session := Session{
 131: 			Index:                     i,
 132: 			SessionID:                 meta.SessionID,
 133: 			CreatedAt:                 meta.CreatedAt,
 134: 			Strategy:                  meta.Strategy,
 135: 			Branch:                    meta.Branch,
 136: 			CommitSHA:                 meta.CommitSHA,
 137: 			CheckpointsCount:          meta.CheckpointsCount,
 138: 			SaveStepCount:             meta.SaveStepCount,
 139: 			FilesTouched:              appendSortedUnique(nil, meta.FilesTouched...),
 140: 			AgentType:                 string(meta.Agent),
 141: 			Model:                     meta.Model,
 142: 			TurnID:                    meta.TurnID,
 143: 			Kind:                      meta.Kind,
 144: 			TokenUsage:                meta.TokenUsage,
 145: 			TranscriptStart:           meta.GetTranscriptStart(),
 146: 			CompactTranscriptStart:    meta.CompactTranscriptStart,
 147: 			PromptCount:               len(prompts),
 148: 			SkillEventCount:           len(meta.SkillEvents),
 149: 		}
 150: 		if len(content.Transcript) == 0 {
 151: 			session.TranscriptUnavailable = true
 152: 			session.TranscriptUnavailableReason = "session transcript empty or unavailable"
 153: 		}
 154: 		for j, prompt := range prompts {
 155: 			p := Prompt{SessionIndex: i, PromptIndex: j, Text: prompt}
 156: 			session.Prompts = append(session.Prompts, p)
 157: 			ac.ScopedPrompts = append(ac.ScopedPrompts, p)
 158: 			if ac.DeveloperPrompt == "" {
 159: 				ac.DeveloperPrompt = prompt
 160: 			}
 161: 		}
 162: 		if ac.AgentType == "" {
 163: 			ac.AgentType = session.AgentType
 164: 		}
 165: 		if ac.Model == "" {
 166: 			ac.Model = session.Model
 167: 		}
 168: 		ac.Sessions = append(ac.Sessions, session)
 169: 		if session.SessionID != "" {
 170: 			ac.Provenance.SessionIDs = append(ac.Provenance.SessionIDs, session.SessionID)
 171: 		}
 172: 		if len(content.Transcript) > 0 && !ac.Transcript.Available {
 173: 			ac.Transcript = TranscriptRef{Available: true, SessionID: session.SessionID, SessionIndex: i, ByteLength: len(content.Transcript)}
 174: 		}
 175: 	}
 176: 	if !ac.Transcript.Available {
 177: 		ac.Transcript = TranscriptRef{Available: false, UnavailableReason: "no session transcript bytes available"}
 178: 	}
 179: 	ac.Provenance.SessionIDs = appendSortedUnique(nil, ac.Provenance.SessionIDs...)
 180: 	ac.Provenance.Sources = append(ac.Provenance.Sources,
 181: 		EvidenceSource{Kind: "session", ID: strings.Join(ac.Provenance.SessionIDs, ","), Description: "Entire checkpoint session metadata, prompts, and transcript availability", Available: len(ac.Sessions) > 0},
 182: 	)
 183: 	return nil
 184: }
 185: 
 186: func (b Builder) collectGitEvidence(ctx context.Context, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) GitEvidence {
 187: 	if b.Repo == nil {
 188: 		return GitEvidence{DiffUnavailableReason: "git repository not configured", ChangedFilesUnavailable: "git repository not configured"}
 189: 	}
 190: 	commits, err := findAssociatedCommits(ctx, b.Repo, checkpointID, summary.CommitSHA)
 191: 	if err != nil {
 192: 		return GitEvidence{DiffUnavailableReason: err.Error(), ChangedFilesUnavailable: err.Error()}
 193: 	}
 194: 	if len(commits) == 0 {
 195: 		return GitEvidence{DiffUnavailableReason: "no associated commits found", ChangedFilesUnavailable: "no associated commits found"}
 196: 	}
 197: 
 198: 	evidence := GitEvidence{AssociatedCommits: commits}
 199: 	if b.RepoRoot == "" {
 200: 		evidence.DiffUnavailableReason = "repository root not configured"
 201: 		evidence.ChangedFilesUnavailable = "repository root not configured"
 202: 		return evidence
 203: 	}
 204: 	var diff strings.Builder
 205: 	changed := map[string]struct{}{}
 206: 	for _, commit := range commits {
 207: 		parent := firstParentHash(ctx, b.Repo, commit.SHA)
 208: 		files, filesErr := gitops.DiffTreeFileList(ctx, b.RepoRoot, parent, commit.SHA)
 209: 		if filesErr != nil && evidence.ChangedFilesUnavailable == "" {
 210: 			evidence.ChangedFilesUnavailable = filesErr.Error()
 211: 		}
 212: 		for _, file := range files {
 213: 			changed[file] = struct{}{}
 214: 		}
 215: 		patch, patchErr := gitShowPatch(ctx, b.RepoRoot, commit.SHA)
 216: 		if patchErr != nil {
 217: 			if evidence.DiffUnavailableReason == "" {
 218: 				evidence.DiffUnavailableReason = patchErr.Error()
 219: 			}
 220: 			continue
 221: 		}
 222: 		if diff.Len() > 0 {
 223: 			diff.WriteString("\n")
 224: 		}
 225: 		diff.WriteString(patch)
 226: 	}
 227: 	evidence.ChangedFiles = fileChangesFromSet(changed)
 228: 	evidence.ChangedFilesUnavailable = emptyIfChanged(evidence.ChangedFilesUnavailable, changed)
 229: 	evidence.Diff = diff.String()
 230: 	if evidence.Diff != "" {
 231: 		evidence.DiffUnavailableReason = ""
 232: 	}
 233: 	return evidence
 234: }
 235: 
 236: func findAssociatedCommits(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, anchorSHA string) ([]AssociatedCommit, error) {
 237: 	seen := map[string]bool{}
 238: 	var result []AssociatedCommit
 239: 	if anchorSHA != "" {
 240: 		commit, err := repo.CommitObject(plumbing.NewHash(anchorSHA))
 241: 		if err == nil {
 242: 			result = append(result, associatedCommit(commit, "checkpoint_metadata"))
 243: 			seen[commit.Hash.String()] = true
 244: 		}
 245: 	}
 246: 
 247: 	head, err := repo.Head()
 248: 	if err != nil {
 249: 		if len(result) > 0 {
 250: 			return result, nil
 251: 		}
 252: 		return nil, fmt.Errorf("resolve HEAD: %w", err)
 253: 	}
 254: 	iter, err := repo.Log(&git.LogOptions{From: head.Hash(), Order: git.LogOrderCommitterTime})
 255: 	if err != nil {
 256: 		if len(result) > 0 {
 257: 			return result, nil
 258: 		}
 259: 		return nil, fmt.Errorf("read git log: %w", err)
 260: 	}
 261: 	defer iter.Close()
 262: 	err = iter.ForEach(func(commit *object.Commit) error {
 263: 		if err := ctx.Err(); err != nil {
 264: 			return err
 265: 		}
 266: 		for _, cpID := range trailers.ParseAllCheckpoints(commit.Message) {
 267: 			if cpID == checkpointID && !seen[commit.Hash.String()] {
 268: 				result = append(result, associatedCommit(commit, "commit_trailer"))
 269: 				seen[commit.Hash.String()] = true
 270: 				break
 271: 			}
 272: 		}
 273: 		return nil
 274: 	})
 275: 	if err != nil {
 276: 		return nil, err
 277: 	}
 278: 	return result, nil
 279: }
 280: 
 281: func associatedCommit(commit *object.Commit, source string) AssociatedCommit {
 282: 	subject, _, _ := strings.Cut(commit.Message, "\n")
 283: 	return AssociatedCommit{
 284: 		SHA:     commit.Hash.String(),
 285: 		Subject: strings.TrimSpace(subject),
 286: 		Author:  commit.Author.Name,
 287: 		Date:    commit.Author.When,
 288: 		Source:  source,
 289: 	}
 290: }
 291: 
 292: func firstParentHash(ctx context.Context, repo *git.Repository, sha string) string {
 293: 	commit, err := repo.CommitObject(plumbing.NewHash(sha))
 294: 	if err != nil || commit.NumParents() == 0 {
 295: 		return ""
 296: 	}
 297: 	parent, err := commit.Parent(0)
 298: 	if err != nil {
 299: 		return ""
 300: 	}
 301: 	if err := ctx.Err(); err != nil {
 302: 		return ""
 303: 	}
 304: 	return parent.Hash.String()
 305: }
 306: 
 307: func gitShowPatch(ctx context.Context, repoRoot, sha string) (string, error) {
 308: 	cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "show", "--format=commit %H%n%B", "--no-ext-diff", "--find-renames", sha)
 309: 	var stdout, stderr bytes.Buffer
 310: 	cmd.Stdout = &stdout
 311: 	cmd.Stderr = &stderr
 312: 	if err := cmd.Run(); err != nil {
 313: 		return "", fmt.Errorf("git show %s: %w: %s", sha, err, strings.TrimSpace(stderr.String()))
 314: 	}
 315: 	return stdout.String(), nil
 316: }
 317: 
 318: func fileChangesFromSet(paths map[string]struct{}) []FileChange {
 319: 	out := make([]FileChange, 0, len(paths))
 320: 	for path := range paths {
 321: 		out = append(out, FileChange{Path: path})
 322: 	}
 323: 	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
 324: 	return out
 325: }
 326: 
 327: func commitSHAs(commits []AssociatedCommit) []string {
 328: 	out := make([]string, 0, len(commits))
 329: 	for _, commit := range commits {
 330: 		out = append(out, commit.SHA)
 331: 	}
 332: 	return out
 333: }
 334: 
 335: func appendSortedUnique(dst []string, values ...string) []string {
 336: 	seen := map[string]struct{}{}
 337: 	for _, existing := range dst {
 338: 		seen[existing] = struct{}{}
 339: 	}
 340: 	for _, value := range values {
 341: 		if value == "" {
 342: 			continue
 343: 		}
 344: 		if _, ok := seen[value]; ok {
 345: 			continue
 346: 		}
 347: 		seen[value] = struct{}{}
 348: 		dst = append(dst, value)
 349: 	}
 350: 	sort.Strings(dst)
 351: 	return dst
 352: }
 353: 
 354: func emptyIfChanged(reason string, changed map[string]struct{}) string {
 355: 	if len(changed) > 0 {
 356: 		return ""
 357: 	}
 358: 	return reason
 359: }

